from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_account_dict, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
FACTOR_WEIGHTS = {
    "miner_3_20280113_relative_reversal_3d": 0.50,
    "miner_3_clv_1d": 0.20,
    "peer_median_leadlag_5d": 0.15,
    "miner_2_risk_adjusted_momentum_20d": 0.15,
}
DIRECTIONS = {k: 1 for k in FACTOR_WEIGHTS}
MIN_W, MAX_W, REBALANCE_DAYS = 0.015, 0.16, 10
last_date = None


def rank(v):
    out = {s: 0.5 for s in UNIVERSE}
    good = sorted((s, float(x)) for s, x in v.items() if np.isfinite(x))
    if len(good) >= 2:
        for i, (s, _) in enumerate(good):
            out[s] = (i + 1.0) / len(good)
    return out


def bounded(raw):
    # Iterative box/simplex projection; all 15 assets remain represented.
    w = {s: max(0.0, float(raw.get(s, 0.0))) for s in UNIVERSE}
    z = sum(w.values()) or 1.0
    w = {s: x / z for s, x in w.items()}
    fixed = {}
    for _ in range(50):
        changed = False
        for s in UNIVERSE:
            if s not in fixed and w[s] < MIN_W:
                fixed[s] = MIN_W; w[s] = MIN_W; changed = True
            elif s not in fixed and w[s] > MAX_W:
                fixed[s] = MAX_W; w[s] = MAX_W; changed = True
        free = [s for s in UNIVERSE if s not in fixed]
        if not changed or not free:
            break
        rem = 1.0 - sum(fixed.values())
        free_sum = sum(w[s] for s in free) or 1.0
        for s in free:
            w[s] = rem * w[s] / free_sum
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_date
    market = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=90)
        if df is None or len(df) < 25:
            continue
        df = df.sort_values("date").reset_index(drop=True)
        c = np.asarray(df["close"], dtype=float)
        h = np.asarray(df["high"], dtype=float)
        l = np.asarray(df["low"], dtype=float)
        r = c[1:] / np.maximum(c[:-1], 1e-12) - 1.0
        market[s] = (c, h, l, r, str(df.iloc[-1]["date"]))
    if len(market) < 12:
        return
    decision = max(x[4] for x in market.values())
    if last_date is not None:
        try:
            if (np.datetime64(decision, "D") - np.datetime64(last_date, "D")) / np.timedelta64(1, "D") < REBALANCE_DAYS:
                return
        except Exception:
            return

    relative, clv, peer, momentum, invvol = {}, {}, {}, {}, {}
    five_day = {}
    for s, (c, h, l, r, _) in market.items():
        if len(c) < 22:
            continue
        vol = max(float(np.std(r[-20:])), 0.008)
        # Newly selected relative reversal: outperformers over 3d are faded.
        relative[s] = -float(c[-1] / max(c[-4], 1e-12) - 1.0)
        # CLV one-day positioning, using only the last completed bar.
        clv[s] = float((2.0*c[-1] - h[-1] - l[-1]) / max(h[-1]-l[-1], 1e-12))
        five_day[s] = float(c[-1] / max(c[-6], 1e-12) - 1.0)
        momentum[s] = float((c[-1] / max(c[-21], 1e-12) - 1.0) / (vol + 0.01))
        invvol[s] = 1.0 / vol
    med5 = float(np.median(list(five_day.values())))
    peer = {s: five_day[s] - med5 for s in five_day}
    factors = {"miner_3_20280113_relative_reversal_3d": rank(relative),
               "miner_3_clv_1d": rank(clv),
               "peer_median_leadlag_5d": rank(peer),
               "miner_2_risk_adjusted_momentum_20d": rank(momentum)}
    score = {s: sum(FACTOR_WEIGHTS[k] * DIRECTIONS[k] * factors[k].get(s, 0.5) for k in FACTOR_WEIGHTS) for s in UNIVERSE}

    # High-volatility, mildly bearish regime: stay fully invested but favor defensive benchmarks.
    if "SPX" in market:
        spx = market["SPX"][0]
        if spx[-1] < spx[-6] and spx[-1] < spx[-21]:
            for s in ("XAU", "US10Y", "CN10Y"):
                score[s] += 0.12
            for s in ("BTC", "ETH", "WTI"):
                score[s] = max(0.05, score[s] - 0.08)
    mean_iv = float(np.mean(list(invvol.values())))
    raw = {s: max(0.01, score[s]) * (0.80 + 0.20 * invvol.get(s, mean_iv) / max(mean_iv, 1e-12)) for s in UNIVERSE}
    weights = bounded(raw)
    vals = np.array([score[s] for s in UNIVERSE], dtype=float)
    scale = max(float(np.std(vals)), 1e-12)
    forecast_returns = {s: float(0.01 * (score[s] - float(np.mean(vals))) / scale) for s in UNIVERSE}
    ensemble_path = Path(__file__).parent / "factors" / "factor_ensemble.json"
    try:
        data = json.loads(ensemble_path.read_text())
        factor_ids = [str(x["factor_id"]) for x in data.get("selected_factors", [])[:10]]
    except Exception:
        factor_ids = list(FACTOR_WEIGHTS)
    rebalance_to_weights(weights, forecast_returns=forecast_returns, factor_ids=factor_ids, horizon_days=10)
    last_date = decision

