import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE_PATH = Path(__file__).parent / "factors/factor_ensemble.json"
MIN_W, MAX_W = 0.015, 0.16
last_date = None


def rank(values):
    out = {s: 0.5 for s in UNIVERSE}
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.0) / len(good) if len(good) > 1 else 0.5
    return out


def bounded(raw):
    # Projection to a full-investment simplex with modest diversification bounds.
    w = {s: max(0.0, float(raw.get(s, 0.0))) for s in UNIVERSE}
    z = sum(w.values()) or 1.0
    w = {s: x / z for s, x in w.items()}
    for _ in range(50):
        low = [s for s in UNIVERSE if w[s] < MIN_W]
        high = [s for s in UNIVERSE if w[s] > MAX_W]
        if not low and not high:
            break
        fixed = set(low + high)
        for s in low: w[s] = MIN_W
        for s in high: w[s] = MAX_W
        free = [s for s in UNIVERSE if s not in fixed]
        if not free: break
        rem = 1.0 - sum(w[s] for s in fixed)
        free_sum = sum(w[s] for s in free) or 1.0
        for s in free: w[s] = rem * w[s] / free_sum
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_date
    try:
        ensemble = json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not ensemble or abs(sum(float(x["weight"]) for x in ensemble) - 1.0) > 1e-6:
        return
    factor_ids = [str(x["factor_id"]) for x in ensemble]
    directions = {str(x["factor_id"]): float(x.get("direction", 1)) for x in ensemble}
    factor_weights = {str(x["factor_id"]): float(x["weight"]) for x in ensemble}

    market = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=110)
        if df is None or len(df) < 65: continue
        df = df.sort_values("date").reset_index(drop=True)
        c = np.asarray(df["close"], dtype=float)
        h = np.asarray(df["high"], dtype=float)
        l = np.asarray(df["low"], dtype=float)
        r = c[1:] / np.maximum(c[:-1], 1e-12) - 1.0
        market[s] = (c, h, l, r, str(df.iloc[-1]["date"]))
    if len(market) < 12: return
    decision = max(x[4] for x in market.values())
    if last_date is not None:
        try:
            # Approximately ten trading sessions, excluding weekends.
            if (np.datetime64(decision, "D") - np.datetime64(last_date, "D")) / np.timedelta64(1, "D") < 13:
                return
        except Exception:
            return

    three = {s: x[0][-1] / max(x[0][-4], 1e-12) - 1.0 for s, x in market.items()}
    three_mean = float(np.mean(list(three.values())))
    three_disp = float(np.std(list(three.values())))
    # The dispersion-conditioned factor is null outside a high-dispersion regime.
    hist_disp = []
    n = len(next(iter(market.values()))[0])
    for j in range(4, n):
        vals = [x[0][j] / max(x[0][j-3], 1e-12) - 1.0 for x in market.values()]
        hist_disp.append(float(np.std(vals)))
    high_disp = three_disp > float(np.median(hist_disp[-60:])) if hist_disp else False
    five = {s: x[0][-1] / max(x[0][-6], 1e-12) - 1.0 for s, x in market.items()}
    peer_median = float(np.median(list(five.values())))
    raw_factors = {fid: {} for fid in factor_ids}
    invvol = {}
    for s, (c, h, l, r, _) in market.items():
        v20 = max(float(np.std(r[-20:], ddof=1)), 0.008)
        v60 = max(float(np.std(r[-60:], ddof=1)), 0.008)
        raw_factors.setdefault("miner_2_volscaled_trend_10d", {})[s] = (c[-1] / max(c[-21], 1e-12) - 1) / v20
        raw_factors.setdefault("miner_2_risk_adjusted_momentum_20d", {})[s] = (c[-1] / max(c[-21], 1e-12) - 1) / (v60 * np.sqrt(20))
        raw_factors.setdefault("miner_3_20280113_relative_reversal_3d", {})[s] = - (three[s] - three_mean)
        raw_factors.setdefault("miner_3_20280127_dispersion_relative_reversal_3d", {})[s] = -(three[s] - three_mean) if high_disp else np.nan
        raw_factors.setdefault("peer_median_leadlag_5d", {})[s] = peer_median
        raw_factors.setdefault("miner_3_clv_1d", {})[s] = (2*c[-1] - h[-1] - l[-1]) / max(h[-1] - l[-1], 1e-12)
        invvol[s] = 1.0 / v20
    ranked = {fid: rank(raw_factors.get(fid, {})) for fid in factor_ids}
    score = {s: sum(factor_weights[fid] * directions[fid] * ranked[fid].get(s, 0.5) for fid in factor_ids) for s in UNIVERSE}

    # High-risk mildly bearish regime: rotate toward tradable defensives, never cash.
    spx = market.get("SPX")
    if spx is not None and spx[0][-1] < spx[0][-6] and spx[0][-1] < spx[0][-21]:
        for s in ("XAU", "US10Y", "CN10Y"): score[s] += 0.10
        for s in ("BTC", "ETH", "WTI"): score[s] = max(0.05, score[s] - 0.06)
    mean_iv = float(np.mean(list(invvol.values())))
    raw = {s: max(0.01, score[s]) * (0.85 + 0.15 * invvol[s] / max(mean_iv, 1e-12)) for s in UNIVERSE}
    weights = bounded(raw)
    score_mean = float(np.mean([score[s] for s in UNIVERSE]))
    scale = max(float(np.std(list(score.values()))), 1e-12)
    forecast_returns = {s: float(0.01 * (score[s] - score_mean) / scale) for s in UNIVERSE}
    rebalance_to_weights(weights, forecast_returns=forecast_returns, factor_ids=factor_ids, horizon_days=10)
    last_date = decision

