import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE_PATH = Path(__file__).parent / "factors/factor_ensemble.json"
MIN_W, MAX_W = 0.015, 0.16
last_decision = None


def ranks(values):
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    n = len(good)
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1) / n if n > 1 else 0.5
    return out


def project(raw):
    w = {s: max(0.0, float(raw.get(s, 0.0))) for s in UNIVERSE}
    total = sum(w.values()) or 1.0
    w = {s: x / total for s, x in w.items()}
    # Simple capped simplex projection by iterative redistribution.
    for _ in range(20):
        low = [s for s in UNIVERSE if w[s] < MIN_W]
        high = [s for s in UNIVERSE if w[s] > MAX_W]
        if not low and not high:
            break
        fixed = set(low + high)
        for s in low: w[s] = MIN_W
        for s in high: w[s] = MAX_W
        free = [s for s in UNIVERSE if s not in fixed]
        rem = 1.0 - sum(w[s] for s in fixed)
        fs = sum(w[s] for s in free) or 1.0
        for s in free: w[s] = max(0.0, rem) * w[s] / fs
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}


def vix_stressed():
    try:
        d = get_index_daily_data(symbol="VIX", days=65)
        if d is None or len(d) < 30:
            return False
        x = np.asarray(d.sort_values("date")["close"], dtype=float)
        return bool(x[-1] > np.median(x[-30:]))
    except Exception:
        return False


@register_hook
def cross_asset_strategy():
    global last_decision
    try:
        ens = json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not ens or abs(sum(float(x.get("weight", 0)) for x in ens) - 1.0) > 1e-6:
        return
    factor_ids = [str(x["factor_id"]) for x in ens]
    fw = {str(x["factor_id"]): float(x["weight"]) for x in ens}
    direction = {str(x["factor_id"]): float(x.get("direction", 1)) for x in ens}
    data = {}
    for s in UNIVERSE:
        d = get_stock_daily_data(symbol=s, days=100)
        if d is None or len(d) < 65:
            continue
        d = d.sort_values("date").reset_index(drop=True)
        c = np.asarray(d["close"], dtype=float)
        data[s] = (c, str(d.iloc[-1]["date"]))
    if len(data) < 12:
        return
    decision = max(v[1] for v in data.values())
    if last_decision is not None:
        try:
            if (np.datetime64(decision) - np.datetime64(last_decision)) / np.timedelta64(1, "D") < 13:
                return
        except Exception:
            return

    ret3 = {s: c[-1] / max(c[-4], 1e-12) - 1 for s, (c, _) in data.items()}
    ret1 = {s: c[-1] / max(c[-2], 1e-12) - 1 for s, (c, _) in data.items()}
    mean3 = float(np.mean(list(ret3.values())))
    dispersion = float(np.std(list(ret3.values())))
    hist_disp = []
    for j in range(4, len(next(iter(data.values()))[0])):
        hist_disp.append(float(np.std([c[j] / max(c[j-3], 1e-12) - 1 for c, _ in data.values()])))
    high_disp = bool(hist_disp and dispersion > np.median(hist_disp[-60:]))
    stressed = vix_stressed()
    factors = {fid: {} for fid in factor_ids}
    invvol = {}
    for s, (c, _) in data.items():
        daily = c[1:] / np.maximum(c[:-1], 1e-12) - 1
        v20 = max(float(np.std(daily[-20:], ddof=1)), 0.008)
        v60 = max(float(np.std(daily[-60:], ddof=1)), 0.008)
        trend = (c[-1] / max(c[-11], 1e-12) - 1) / v20
        mom = (c[-1] / max(c[-21], 1e-12) - 1) / (v60 * np.sqrt(20))
        factors.setdefault("miner_2_volscaled_trend_10d", {})[s] = trend
        factors.setdefault("miner_2_risk_adjusted_momentum_20d", {})[s] = mom
        factors.setdefault("miner_1_vix_conditioned_reversal_5d", {})[s] = (-(c[-1] / max(c[-6], 1e-12) - 1)) if stressed else 0.0
        factors.setdefault("miner_2_dispersion_conditioned_reversal_1d", {})[s] = -ret1[s] if high_disp else 0.0
        factors.setdefault("miner_3_20280127_dispersion_relative_reversal_3d", {})[s] = -(ret3[s] - mean3) if high_disp else 0.0
        invvol[s] = 1.0 / v20
    rr = {fid: ranks(factors.get(fid, {})) for fid in factor_ids}
    score = {s: sum(fw[fid] * direction[fid] * rr[fid].get(s, .5) for fid in factor_ids) for s in UNIVERSE}
    spx = data.get("SPX")
    bearish = spx is not None and spx[0][-1] < spx[0][-6] and spx[0][-1] < spx[0][-21]
    if bearish or stressed:
        for s in ("XAU", "US10Y", "CN10Y"): score[s] += 0.08
        for s in ("BTC", "ETH", "WTI"): score[s] = max(0.05, score[s] - 0.05)
    avg_iv = np.mean(list(invvol.values()))
    raw = {s: max(.01, score[s]) * (.85 + .15 * invvol[s] / max(avg_iv, 1e-12)) for s in UNIVERSE}
    weights = project(raw)
    mu, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-12)
    forecast_returns = {s: float(.01 * (score[s] - mu) / sd) for s in UNIVERSE}
    rebalance_to_weights(weights, forecast_returns=forecast_returns, factor_ids=factor_ids, horizon_days=10)
    last_decision = decision

