        up20, dn20 = r[-20:][r[-20:] > 0], r[-20:][r[-20:] < 0]
        up60, dn60 = r[-60:][r[-60:] > 0], r[-60:][r[-60:] < 0]
        su20 = np.std(up20, ddof=1) if len(up20) > 1 else 0.0
        sd20 = np.std(dn20, ddof=1) if len(dn20) > 1 else v20
        su60 = np.std(up60, ddof=1) if len(up60) > 1 else 0.0
        sd60 = np.std(dn60, ddof=1) if len(dn60) > 1 else v60
        signals.setdefault("miner_1_20280713_upside_volatility_advantage_20d", {})[s] = (su20 - sd20) / (su20 + sd20 + 1e-8)
        # Higher score means smaller relative downside shocks (safer).
        signals.setdefault("miner_1_20280629_downside_volatility_60d", {})[s] = -(sd60 - su60) / (sd60 + su60 + 1e-8)
        ar, br = r[-40:], bench_r[-40:]
        mask = br < 0
        signals.setdefault("miner_1_downside_capture_40d", {})[s] = (-(np.mean(ar[mask]) / np.mean(br[mask]))
            if np.any(mask) and abs(np.mean(br[mask])) > 1e-9 else 0.0)
        signals.setdefault("miner_2_risk_adjusted_momentum_20d", {})[s] = (c[-1] / c[-21] - 1.0) / (v60 * np.sqrt(20))
        signals.setdefault("miner_2_volscaled_trend_10d", {})[s] = (c[-1] / c[-11] - 1.0) / v20
        lo, hi = np.min(c[-60:]), np.max(c[-60:])
        pos = (c[-1] - lo) / (hi - lo + 1e-8)
        signals.setdefault("miner_2_20280727_range_position_momentum_1d", {})[s] = -(c[-1] / c[-21] - 1.0) * (0.5 + pos)
        invvol[s] = 1.0 / v20

    score = {s: sum(fweights[f] * dirs[f] * rank_cs(signals.get(f, {}))[s] for f in fids) for s in UNIVERSE}
    bearish = len(bench) >= 21 and bench[-1] < bench[-6] and bench[-1] < bench[-21]
    if bearish or vix_stressed():
        for s in ("XAU", "US10Y", "CN10Y"): score[s] += 0.08
        for s in ("BTC", "ETH", "WTI"): score[s] -= 0.05
    avg_iv = np.mean(list(invvol.values()))
    raw = {s: max(0.01, score[s]) * (0.85 + 0.15 * invvol.get(s, avg_iv) / avg_iv) for s in UNIVERSE}
    target = bound_weights(raw)
    mean, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-9)
    forecast = {s: float(0.01 * (score[s] - mean) / sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=fids, horizon_days=10)

