import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE_PATH = Path(__file__).parent / "factors/factor_ensemble.json"
MIN_W, MAX_W = 0.015, 0.16
last_decision = None


def rank_cs(vals):
    good = sorted((s, float(v)) for s, v in vals.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if good:
        for i, (s, _) in enumerate(good):
            out[s] = (i + 1.0) / len(good)
    return out


def bounded(raw):
    w = {s: max(float(raw.get(s, 0.0)), 1e-9) for s in UNIVERSE}
    # Iterative water filling keeps every tradable instrument invested.
    fixed = {}
    for _ in range(30):
        z = sum(w.values())
        w = {s: x / z for s, x in w.items()}
        changed = False
        for s in UNIVERSE:
            if s not in fixed and w[s] < MIN_W:
                fixed[s] = MIN_W; w[s] = MIN_W; changed = True
            elif s not in fixed and w[s] > MAX_W:
                fixed[s] = MAX_W; w[s] = MAX_W; changed = True
        if not changed:
            break
        free = [s for s in UNIVERSE if s not in fixed]
        rem = 1.0 - sum(fixed.values())
        fs = sum(w[s] for s in free)
        if free and fs > 0:
            for s in free: w[s] *= rem / fs
    z = sum(w.values())
    return {s: max(0.0, w[s] / z) for s in UNIVERSE}


def stressed():
    try:
        d = get_index_daily_data("VIX", 65)
        x = np.asarray(d.sort_values("date")["close"], float)
        return len(x) >= 30 and x[-1] > np.median(x[-30:])
    except Exception:
        return False


@register_hook
def cross_asset_strategy():
    global last_decision
    try:
        fs = json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not fs or abs(sum(float(f["weight"]) for f in fs) - 1.0) > 1e-6:
        return
    fids = [str(f["factor_id"]) for f in fs]
    weights = {str(f["factor_id"]): float(f["weight"]) for f in fs}
    directions = {str(f["factor_id"]): float(f.get("direction", 1)) for f in fs}

    data = {}
    for s in UNIVERSE:
        d = get_stock_daily_data(s, 150)
        if d is None or len(d) < 65: continue
