UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors/factor_ensemble.json"
_calls = 0

def cs_rank(values):
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if good:
        for i, (s, _) in enumerate(good):
            out[s] = (i + 1.0) / len(good)
    return out

def normalize_weights(raw):
    # Mild concentration control, with full investment in the 15 tradables.
    w = {s: max(float(raw.get(s, 0.01)), 1e-8) for s in UNIVERSE}
    for _ in range(30):
        z = sum(w.values())
        w = {s: v / z for s, v in w.items()}
        low = [s for s in UNIVERSE if w[s] < 0.015]
        high = [s for s in UNIVERSE if w[s] > 0.14]
        if not low and not high:
            break
        for s in low: w[s] = 0.015
        for s in high: w[s] = 0.14
    z = sum(w.values())
    return {s: float(w[s] / z) for s in UNIVERSE}

def stressed():
    try:
        d = get_index_daily_data("VIX", 65)
        x = np.asarray(d.sort_values("date")["close"], dtype=float)
        return len(x) >= 60 and x[-1] > np.median(x[-60:])
    except Exception:
        return False

@register_hook
def cross_asset_strategy():
    global _calls
    _calls += 1
    if (_calls - 1) % 10:
        return
    try:
        selected = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not selected or abs(sum(float(x["weight"]) for x in selected) - 1.0) > 1e-5:
        return
    factor_ids = [x["factor_id"] for x in selected]
    factor_weights = {x["factor_id"]: float(x["weight"]) * float(x.get("direction", 1)) for x in selected}
    prices = {}
    for s in UNIVERSE:
        d = get_stock_daily_data(s, 150)
        if d is None or len(d) < 70:
            continue
        c = np.asarray(d.sort_values("date")["close"], dtype=float)
        if len(c) >= 70 and np.all(np.isfinite(c)) and np.all(c > 0):
            prices[s] = c
