        neg60, pos60 = r60[r60 < 0], r60[r60 > 0]
        dn60 = float(np.std(neg60, ddof=1)) if len(neg60) > 1 else v60
        dn20 = float(np.std(neg20, ddof=1)) if len(neg20) > 1 else v20
        up20 = float(np.std(pos20, ddof=1)) if len(pos20) > 1 else 0.0
        ret10 = c[-1] / c[-11] - 1.0
        ret20 = c[-1] / c[-21] - 1.0
        vals = {
          "miner_1_20280629_downside_volatility_60d": -dn60,
          "miner_2_volscaled_trend_10d": ret10 / v20,
          "miner_1_20280713_upside_volatility_advantage_20d": (up20 - dn20) / (up20 + dn20 + 1e-9),
          "miner_1_vix_conditioned_relative_reversal_20d": (-ret20 if hv else 0.0),
          "miner_3_20281102_voladjusted_acceleration_10d": (ret10 - (c[-6] / c[-16] - 1.0)) / v20,
        }
        for f in factor_ids:
            raw[f][s] = vals.get(f, 0.0)
