    bearish = prices["SPX"][-1] < prices["SPX"][-6] and prices["SPX"][-1] < prices["SPX"][-21]
    if bearish or hv:
        for s in ("XAU", "US10Y", "CN10Y"): scores[s] += 0.10
        for s in ("BTC", "ETH", "WTI"): scores[s] -= 0.05
    mean_iv = float(np.mean(list(invvol.values())))
    raw_w = {s: max(scores[s], 0.01) * (0.85 + 0.15 * invvol.get(s, mean_iv) / mean_iv) for s in UNIVERSE}
    target = normalize_weights(raw_w)
    a = np.asarray(list(scores.values()), dtype=float)
    sd = max(float(np.std(a)), 1e-9)
    forecast = {s: float(0.01 * (scores[s] - float(np.mean(a))) / sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)

