from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors/factor_ensemble.json"
_calls = 0


def ranks(values):
    good = [(s, v) for s, v in values.items() if np.isfinite(v)]
    out = {s: 0.5 for s in UNIVERSE}
    if not good:
        return out
    good.sort(key=lambda x: x[1])
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.0) / len(good)
    return out


def stressed():
    try:
        d = get_index_daily_data("VIX", 65)
        x = np.asarray(d.sort_values("date")["close"], dtype=float)
        return len(x) >= 60 and x[-1] >= np.median(x[-60:])
    except Exception:
        return False


def make_weights(score):
    # Defensive, diversified full investment; no cash sleeve.
    z = np.array([score[s] for s in UNIVERSE], dtype=float)
    z = (z - z.mean()) / max(z.std(), 1e-9)
    raw = np.exp(np.clip(0.55 * z, -1.8, 1.8))
    w = raw / raw.sum()
    # Keep the 15-name cross-section diversified and cap concentration.
    w = np.maximum(w, 0.01)
    w = w / w.sum()
    for _ in range(10):
        excess = np.maximum(w - 0.14, 0).sum()
        if excess < 1e-10:
            break
        w = np.minimum(w, 0.14)
        room = np.maximum(0.14 - w, 0)
        w += excess * room / max(room.sum(), 1e-12)
        w /= w.sum()
    return {s: float(w[i]) for i, s in enumerate(UNIVERSE)}


@register_hook
def cross_asset_strategy():
    global _calls
    _calls += 1
    if (_calls - 1) % 10:
        return
    try:
        selected = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not selected or abs(sum(float(f.get("weight", 0)) for f in selected) - 1.0) > 1e-6:
        return
    factor_ids = [f["factor_id"] for f in selected]
    factor_weights = {f["factor_id"]: float(f["weight"]) * float(f.get("direction", 1)) for f in selected}

    prices = {}
    for symbol in UNIVERSE:
        d = get_stock_daily_data(symbol, 150)
        if d is None or len(d) < 70:
            continue
        c = np.asarray(d.sort_values("date")["close"], dtype=float)
        if np.all(np.isfinite(c)) and np.all(c > 0):
            prices[symbol] = c
    if len(prices) < 12:
        return

    high_vix = stressed()
    returns20 = {}
    raw = {f: {} for f in factor_ids}
    invvol = {}
    for symbol, c in prices.items():
        r = c[1:] / c[:-1] - 1.0
        v20 = max(float(np.std(r[-20:], ddof=1)), 0.008)
        v60 = max(float(np.std(r[-60:], ddof=1)), 0.008)
        neg60 = r[-60:][r[-60:] < 0]
        neg20 = r[-20:][r[-20:] < 0]
        pos20 = r[-20:][r[-20:] > 0]
        down60 = float(np.std(neg60, ddof=1)) if len(neg60) > 1 else v60
        down20 = float(np.std(neg20, ddof=1)) if len(neg20) > 1 else v20
        up20 = float(np.std(pos20, ddof=1)) if len(pos20) > 1 else 0.0
        ret10 = c[-1] / c[-11] - 1.0
        ret20 = c[-1] / c[-21] - 1.0
        returns20[symbol] = ret20
        features = {
            "miner_1_20280629_downside_volatility_60d": -down60,
            "miner_1_20280713_upside_volatility_advantage_20d": (up20 - down20) / (up20 + down20 + 1e-9),
            "miner_2_20280127_volscaled_trend_10d": ret10 / v20,
        }
        for f in factor_ids:
            raw[f][symbol] = features.get(f, 0.0)
        invvol[symbol] = 1.0 / v20

    median20 = float(np.median(list(returns20.values())))
    for symbol in prices:
        raw.setdefault("miner_3_20290222_vix_gated_relative_reversal", {})[symbol] = (-returns20[symbol] if high_vix else 0.0)
        raw.setdefault("miner_3_20290208_relative_residual_reversal_20d", {})[symbol] = -(returns20[symbol] - median20)
    ranked = {f: ranks(raw[f]) for f in factor_ids}
    score = {s: sum(factor_weights[f] * ranked[f].get(s, 0.5) for f in factor_ids) for s in UNIVERSE}

    # Bear/high-VIX posture: tilt toward tradable defensive benchmarks.
    spx = prices.get("SPX")
    bearish = spx is not None and spx[-1] < spx[-21]
    if high_vix or bearish:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += 0.08
        for s in ("BTC", "ETH", "WTI"):
            score[s] -= 0.04
    avg_iv = float(np.mean(list(invvol.values())))
    score = {s: score[s] * (0.92 + 0.08 * invvol.get(s, avg_iv) / avg_iv) for s in UNIVERSE}
    target = make_weights(score)
    a = np.array(list(score.values()), dtype=float)
    scale = max(float(a.std()), 1e-9)
    forecast = {s: float(0.01 * (score[s] - a.mean()) / scale) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)

