    z = np.asarray([score[s] for s in UNIVERSE], dtype=float)
    z = (z - z.mean()) / max(z.std(), 1e-9)
    w = np.exp(np.clip(0.50 * z, -1.7, 1.7))
    w /= w.sum()
    w = np.maximum(w, 0.01)
    w /= w.sum()
    # Sensible diversification for a 15-asset universe.
    for _ in range(12):
        excess = float(np.maximum(w - 0.14, 0).sum())
        if excess < 1e-10:
