U = ["000300.SH","SPX","HSI","N225","SX5E","000688.SH","SOX","NDX","XAU","COPPER","WTI","BTC","ETH","US10Y","CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors/factor_ensemble.json"
_calls = 0

def ranks(values):
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in U}
    if good:
        for i, (s, _) in enumerate(good): out[s] = (i + 1.0) / len(good)
    return out

def elevated_vix():
    try:
        d = get_index_daily_data("VIX", 65)
        x = np.asarray(d.sort_values("date")["close"], float)
        return len(x) >= 61 and x[-1] > np.median(x[-61:-1])
    except Exception:
        return False

def weights(score):
    x = np.array([score[s] for s in U], float)
    x = (x - np.mean(x)) / max(np.std(x), 1e-9)
    # High-risk regime: diversified soft concentration, still 100% invested.
    w = np.exp(np.clip(0.24 * x, -0.9, 0.9))
    w = np.maximum(w / w.sum(), 0.012)
    w /= w.sum()
    return {s: float(w[i]) for i, s in enumerate(U)}

@register_hook
def cross_asset_strategy():
    global _calls
    if _calls % 10:
        _calls += 1
        return
    _calls += 1
    try:
        fs = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not fs or abs(sum(float(f["weight"]) for f in fs) - 1.0) > 1e-6:
        return
    ids = [f["factor_id"] for f in fs]
    signed = {f["factor_id"]: float(f["weight"]) * int(f.get("direction", 1)) for f in fs}
    px = {}
    for s in U:
        d = get_stock_daily_data(s, 150)
        if d is not None and len(d) >= 70:
            c = np.asarray(d.sort_values("date")["close"], float)
            if np.all(np.isfinite(c)) and np.all(c > 0): px[s] = c
    if len(px) < 12: return
    ret = {s: px[s][1:] / px[s][:-1] - 1.0 for s in px}
    r5 = {s: px[s][-1] / px[s][-6] - 1 for s in px}
    med5 = np.median(list(r5.values()))
    breadth = sum(v > 0 for v in r5.values()) / len(r5)
    weak = breadth <= 0.40
    highv = elevated_vix()
    market = np.mean(np.array([ret[s][-60:] for s in px]), axis=0)
    raw = {s: {} for s in px}
    for s in px:
        r = ret[s]
        dn60 = r[-60:][r[-60:] < 0]
        dn20 = r[-20:][r[-20:] < 0]
        up20 = r[-20:][r[-20:] > 0]
        sd60 = np.std(dn60, ddof=1) if len(dn60) > 1 else np.std(r[-60:], ddof=1)
        sd20 = np.std(dn20, ddof=1) if len(dn20) > 1 else np.std(r[-20:], ddof=1)
        su20 = np.std(up20, ddof=1) if len(up20) > 1 else 0.0
        raw[s]["miner_1_20280629_downside_volatility_60d"] = -sd60
        raw[s]["miner_1_20280713_upside_volatility_advantage_20d"] = (su20-sd20)/(su20+sd20+1e-9)
