        raw[s]["miner_3_20290222_vix_gated_relative_reversal"] = (-(r[-5:].mean()-med5)) if highv else 0
        raw[s]["miner_2_20290517_vix_residual_vol_reversal_10d"] = (-residual.mean()/sd10) if highv else 0
