import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

U = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX",
     "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors/factor_ensemble.json"
_calls = 0


def ranks(values):
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in U}
    n = len(good)
    if n:
        for i, (s, _) in enumerate(good):
            out[s] = (i + 1.0) / n
    return out


def vix_elevated():
    try:
        d = get_index_daily_data("VIX", 65)
        x = np.asarray(d.sort_values("date")["close"], float)
        return len(x) >= 61 and x[-1] > np.median(x[-61:-1])
    except Exception:
        return False


def make_weights(score):
    x = np.asarray([score[s] for s in U], dtype=float)
    z = (x - x.mean()) / max(x.std(), 1e-9)
    # Deliberately low temperature: the recent live loss argues against
    # concentration in correlated short-horizon reversal signals.
    w = np.exp(np.clip(0.20 * z, -0.70, 0.70))
    w = np.maximum(w / w.sum(), 0.015)
    w /= w.sum()
    return {s: float(w[i]) for i, s in enumerate(U)}


@register_hook
def cross_asset_strategy():
    global _calls
    if _calls % 10:
        _calls += 1
        return
    _calls += 1
    try:
        fs = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not fs or abs(sum(float(f.get("weight", 0)) for f in fs) - 1.0) > 1e-5:
        return
    ids = [f["factor_id"] for f in fs]
    coef = {f["factor_id"]: float(f["weight"]) * int(f.get("direction", 1)) for f in fs}

    px = {}
    for s in U:
        d = get_stock_daily_data(s, 150)
        if d is None or len(d) < 70:
            continue
        c = np.asarray(d.sort_values("date")["close"], float)
        if len(c) >= 70 and np.all(np.isfinite(c)) and np.all(c > 0):
            px[s] = c
    if len(px) < 12:
        return
    ret = {s: px[s][1:] / px[s][:-1] - 1.0 for s in px}
    r5 = {s: px[s][-1] / px[s][-6] - 1.0 for s in px}
    med5 = float(np.median(list(r5.values())))
    breadth = sum(v > 0 for v in r5.values()) / len(r5)
    stressed = breadth <= 0.45 or vix_elevated()
    market = np.mean(np.asarray([ret[s][-60:] for s in px]), axis=0)
    raw = {s: {} for s in px}
    for s in px:
        q = ret[s]
        dn60 = q[-60:][q[-60:] < 0]
        dn20 = q[-20:][q[-20:] < 0]
        up20 = q[-20:][q[-20:] > 0]
        sd60 = np.std(dn60, ddof=1) if len(dn60) > 1 else np.std(q[-60:], ddof=1)
        sd20 = np.std(dn20, ddof=1) if len(dn20) > 1 else np.std(q[-20:], ddof=1)
        su20 = np.std(up20, ddof=1) if len(up20) > 1 else 0.0
        beta = np.cov(q[-60:], market[-60:])[0, 1] / max(np.var(market[-60:]), 1e-9)
        resid5 = q[-5:] - beta * market[-5:]
        sd10 = max(np.std(q[-10:], ddof=1), 0.008)
        rev = -(q[-5:].mean() - med5)
        raw[s]["miner_1_20280629_downside_volatility_60d"] = -sd60
        raw[s]["miner_1_20280713_upside_volatility_advantage_20d"] = (su20 - sd20) / (su20 + sd20 + 1e-9)
        raw[s]["miner_3_20290503_stress_downside_reversal_10d"] = rev / sd10 if stressed else 0.0
        raw[s]["miner_1_20290517_stress_residual_reversal"] = -(resid5.mean()) / sd10 if stressed else 0.0
        raw[s]["miner_3_20290419_breadth_voladjusted_reversal_5d"] = rev / sd10 if stressed else 0.0
        raw[s]["miner_3_20290222_vix_gated_relative_reversal"] = rev if vix_elevated() else 0.0
        raw[s]["miner_3_20290614_downside_risk_trend_reversal_10d"] = -(q[-10:].mean()) / sd10
        raw[s]["miner_2_20290614_stress_downside_residual_reversal_10d"] = -(resid5.mean()) / sd10 if stressed else 0.0
    rr = {f: ranks({s: raw[s].get(f, 0.0) for s in px}) for f in ids}
    score = {s: sum(coef[f] * rr[f][s] for f in ids) for s in U}
    if stressed or breadth < 0.50:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += 0.055
        for s in ("BTC", "ETH", "WTI"):
            score[s] -= 0.025
    target = make_weights(score)
    a = np.asarray([score[s] for s in U], float)
    scale = max(a.std(), 1e-9)
    forecast = {s: float(0.01 * (score[s] - a.mean()) / scale) for s in U}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)

