import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

U = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors/factor_ensemble.json"
_calls = 0

def cross_rank(x):
    good = sorted((s, v) for s, v in x.items() if np.isfinite(v))
    out = {s: .5 for s in U}
    if not good: return out
    for i, (s, _) in enumerate(good): out[s] = (i + 1) / len(good)
    return out

def stressed():
    try:
        d = get_index_daily_data("VIX", 70)
        v = np.asarray(d.sort_values("date")["close"], float)
        return len(v) > 60 and v[-1] > np.median(v[-61:-1])
    except Exception:
        return False

@register_hook
def strategy():
    global _calls
    if _calls % 10:
        _calls += 1
        return
    _calls += 1
    try:
        fs = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not fs or abs(sum(float(f["weight"]) for f in fs) - 1) > 1e-5: return
    ids = [f["factor_id"] for f in fs]
    coef = {f["factor_id"]: float(f["weight"]) * int(f.get("direction", 1)) for f in fs}
    close, vol = {}, {}
    for s in U:
        d = get_stock_daily_data(s, 180)
        if d is None or len(d) < 70: continue
        d = d.sort_values("date")
        c = np.asarray(d["close"], float)
        if np.all(np.isfinite(c)) and np.all(c > 0):
            close[s] = c
            vol[s] = np.asarray(d.get("volume", np.ones(len(d))), float)
    if len(close) < 12: return
    r = {s: close[s][1:] / close[s][:-1] - 1 for s in close}
    m = np.mean([r[s][-60:] for s in close], axis=0)
    breadth = np.mean([np.mean(r[s][-20:]) > 0 for s in close])
    stress = stressed() or breadth < .45
    raw = {s: {} for s in close}
    for s, q in r.items():
        sd10 = max(np.std(q[-10:], ddof=1), .008)
        sd20 = max(np.std(q[-20:], ddof=1), .008)
        dn60 = q[-60:][q[-60:] < 0]
        dn20 = q[-20:][q[-20:] < 0]
        up20 = q[-20:][q[-20:] > 0]
        downvol = np.std(dn60, ddof=1) if len(dn60) > 1 else np.std(q[-60:], ddof=1)
        dvol = np.std(dn20, ddof=1) if len(dn20) > 1 else sd20
        uvol = np.std(up20, ddof=1) if len(up20) > 1 else 0
        beta = np.cov(q[-60:], m)[0, 1] / max(np.var(m), 1e-9)
        resid = q[-5:] - beta * m[-5:]
        med5 = np.median([np.mean(r[x][-5:]) for x in r])
        med10 = np.median([np.mean(r[x][-10:]) for x in r])
        # Each implementation is deliberately simple and uses only completed history.
        vals = {
          "risk_adjusted_momentum_reversal_10d": -(np.mean(q[-60:]) / max(np.std(q[-60:], ddof=1), .008)),
          "vix_gated_relative_reversal": -(np.mean(q[-5:]) - med5) / sd10 if stressed() else 0,
          "stress_residual_reversal": -np.mean(resid) / sd10 if stress else 0,
          "stress_downside_reversal_10d": -(np.mean(q[-10:][q[-10:] < 0]) if np.any(q[-10:] < 0) else 0) / sd10 if stress else 0,
          "downside_volatility_60d": -downvol,
          "upside_volatility_advantage_20d": (uvol-dvol)/(uvol+dvol+1e-9),
          "lowvix_volscaled_trend_30d": np.mean(q[-30:])/max(np.std(q[-30:], ddof=1), .008) if not stressed() else 0,
          "volume_confirmed_reversal_10d": (-(np.mean(q[-10:])-med10)/sd10) * np.clip(np.mean(vol[s][-10:])/max(np.mean(vol[s][-60:]),1e-9), .5, 2),
        }
        for f in ids:
            raw[s][f] = next((v for k,v in vals.items() if k in f), 0.)
    rr = {f: cross_rank({s: raw[s][f] for s in close}) for f in ids}
    score = {s: sum(coef[f] * rr[f][s] for f in ids) for s in U}
    if stress:
        for s in ("XAU", "US10Y", "CN10Y"): score[s] += .06
        for s in ("BTC", "ETH", "WTI"): score[s] -= .03
    a = np.array([score[s] for s in U]); z = (a-a.mean())/max(a.std(),1e-9)
    w = np.maximum(np.exp(np.clip(.18*z, -.65, .65)), .015); w /= w.sum()
    target = {s: float(w[i]) for i,s in enumerate(U)}
    forecast = {s: float(.01*z[i]) for i,s in enumerate(U)}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)

