import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
_calls = 0


def ranks(values):
    good = [(s, float(v)) for s, v in values.items() if np.isfinite(v)]
    good.sort(key=lambda x: x[1])
    out = {s: 0.5 for s in ASSETS}
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.0) / max(len(good), 1)
    return out


def high_vix():
    try:
        d = get_index_daily_data("VIX", 70)
        if d is None or len(d) < 61:
            return False
        x = np.asarray(d.sort_values("date")["close"], float)
        return x[-1] > np.median(x[-61:-1])
    except Exception:
        return False


@register_hook
def strategy():
    global _calls
    if _calls % 10:
        _calls += 1
        return
    _calls += 1
    try:
        factors = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if len(factors) == 0 or abs(sum(float(f["weight"]) for f in factors) - 1.0) > 1e-5:
        return
    ids = [str(f["factor_id"]) for f in factors]
    coef = {str(f["factor_id"]): float(f["weight"]) * int(f.get("direction", 1)) for f in factors}
    closes = {}
    for s in ASSETS:
        d = get_stock_daily_data(s, 220)
        if d is None or len(d) < 70:
            continue
        c = np.asarray(d.sort_values("date")["close"], float)
        if len(c) >= 70 and np.all(np.isfinite(c)) and np.all(c > 0):
            closes[s] = c
    if len(closes) < 12:
        return
    ret = {s: closes[s][1:] / closes[s][:-1] - 1.0 for s in closes}
    market = np.mean([ret[s][-60:] for s in closes], axis=0)
    five = {s: np.mean(ret[s][-5:]) for s in closes}
    ten = {s: np.mean(ret[s][-10:]) for s in closes}
    med5, med10 = np.median(list(five.values())), np.median(list(ten.values()))
    breadth = np.mean([v > 0 for v in five.values()])
    m20, m60 = np.mean(market[-20:]), np.mean(market[-60:])
    vix = high_vix()
    stress, bear = (vix or breadth < .45), (m20 < 0 and m60 < 0)
    raw = {s: {} for s in closes}
    for s, q in ret.items():
        sd10 = max(np.std(q[-10:], ddof=1), .008)
        sd20 = max(np.std(q[-20:], ddof=1), .008)
        sd60 = max(np.std(q[-60:], ddof=1), .008)
        neg20 = q[-20:][q[-20:] < 0]
        neg60 = q[-60:][q[-60:] < 0]
        pos20 = q[-20:][q[-20:] > 0]
        down20 = np.std(neg20, ddof=1) if len(neg20) > 1 else sd20
        down60 = np.std(neg60, ddof=1) if len(neg60) > 1 else sd60
        up20 = np.std(pos20, ddof=1) if len(pos20) > 1 else 0.0
        beta = np.cov(q[-60:], market)[0, 1] / max(np.var(market), 1e-9)
        residual = q[-5:] - beta * market[-5:]
        r60 = closes[s][-1] / closes[s][-61] - 1.0
        path = abs(np.sum(q[-60:])) / max(np.sum(np.abs(q[-60:])), 1e-9)
        inverse_tq = -r60 / max(sd20 * np.sqrt(20), .03) * path
        r40 = closes[s][-1] / closes[s][-41] - 1.0
        worst40 = np.minimum(q[-40:], 0.0)
        tail_resilience = r40 / max(np.sqrt(np.sum(worst40 ** 2)), .03)
        vals = {
            "miner_1_20280810_relative_reversal_5d": -(five[s] - med5) / sd10,
            "miner_1_20290517_stress_residual_reversal": -np.mean(residual) / sd10 if stress else 0.0,
            "miner_3_20290503_stress_downside_reversal_10d": -(np.mean(neg20) if len(neg20) else 0.0) / sd10 if stress else 0.0,
            "miner_3_20290405_extreme_breadth_reversal_5d": -(five[s] - med5) / sd10 if breadth < .35 else 0.0,
            "miner_3_20290222_vix_gated_relative_reversal": -(five[s] - med5) / sd10 if vix else 0.0,
            "miner_2_20290906_regime_neutral_reversal_10d": -(ten[s] - med10) / sd10,
            "miner_3_20290823_risk_adjusted_momentum_reversal_10d": -(closes[s][-11] / closes[s][-41] - 1.0) / max(sd60 * 10.0, .02),
            "miner_1_20280629_downside_volatility_60d": -down60,
            "miner_3_20291129_inverse_trend_quality_10d": inverse_tq,
            "miner_2_20291213_tail_resilience_40d": tail_resilience,
        }
        raw[s] = {fid: vals.get(fid, 0.0) for fid in ids}
    ranked = {fid: ranks({s: raw[s][fid] for s in closes}) for fid in ids}
    score = {s: sum(coef[fid] * ranked[fid][s] for fid in ids) for s in ASSETS}
    if stress:
        for s in ("XAU", "US10Y", "CN10Y"): score[s] += .10
        for s in ("BTC", "ETH", "WTI"): score[s] -= .05
    if bear:
        for s in ("XAU", "US10Y", "CN10Y"): score[s] += .12
        for s in ("BTC", "ETH", "WTI", "SOX", "NDX"): score[s] -= .06
    a = np.array([score[s] for s in ASSETS])
    z = (a - a.mean()) / max(a.std(), 1e-9)
    w = np.maximum(np.exp(np.clip(.12 * z, -.55, .55)), .015)
    w /= w.sum()
    target = {s: float(w[i]) for i, s in enumerate(ASSETS)}
    forecast = {s: float(.01 * z[i]) for i, s in enumerate(ASSETS)}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)

