import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
_calls = 0


def rank_cs(values):
    valid = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in ASSETS}
    for i, (s, _) in enumerate(valid):
        out[s] = (i + 1.0) / len(valid)
    return out


def vix_elevated():
    try:
        d = get_index_daily_data("VIX", 70)
        if d is None or len(d) < 61:
            return False
        x = np.asarray(d.sort_values("date")["close"], float)
        return bool(x[-1] > np.median(x[-61:-1]))
    except Exception:
        return False


@register_hook
def strategy():
    global _calls
    if _calls % 10 != 0:
        _calls += 1
        return
    _calls += 1

    try:
        selected = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not selected:
        return
    total = sum(float(f["weight"]) for f in selected)
    if abs(total - 1.0) > 1e-5:
        return
    factor_ids = [str(f["factor_id"]) for f in selected]
    coef = {str(f["factor_id"]): float(f["weight"]) * int(f.get("direction", 1)) for f in selected}

    closes = {}
    for symbol in ASSETS:
        d = get_stock_daily_data(symbol=symbol, days=220)
        if d is None or len(d) < 70:
            continue
        c = np.asarray(d.sort_values("date")["close"], dtype=float)
        if len(c) >= 70 and np.all(np.isfinite(c)) and np.all(c > 0):
            closes[symbol] = c
    if len(closes) < 12:
        return

    returns = {s: c[1:] / c[:-1] - 1.0 for s, c in closes.items()}
    market = np.mean(np.vstack([returns[s][-60:] for s in closes]), axis=0)
    five = {s: np.mean(returns[s][-5:]) for s in closes}
    ten = {s: np.mean(returns[s][-10:]) for s in closes}
    med5, med10 = np.median(list(five.values())), np.median(list(ten.values()))
    breadth = np.mean([v > 0 for v in five.values()])
    m20, m60 = np.mean(market[-20:]), np.mean(market[-60:])
    vix = vix_elevated()
    stress = vix or breadth < 0.45
    bear = m20 < 0 and m60 < 0

    raw = {s: {} for s in closes}
    for s, r in returns.items():
        sd10 = max(np.std(r[-10:], ddof=1), 0.008)
        sd20 = max(np.std(r[-20:], ddof=1), 0.008)
        sd60 = max(np.std(r[-60:], ddof=1), 0.008)
        neg20 = r[-20:][r[-20:] < 0]
        neg60 = r[-60:][r[-60:] < 0]
        down60 = np.std(neg60, ddof=1) if len(neg60) > 1 else sd60
        beta = np.cov(r[-60:], market)[0, 1] / max(np.var(market), 1e-9)
        residual = r[-5:] - beta * market[-5:]
        r60 = closes[s][-1] / closes[s][-61] - 1.0
        path = abs(np.sum(r[-60:])) / max(np.sum(np.abs(r[-60:])), 1e-9)
        inverse_tq = -r60 / max(sd20 * np.sqrt(20), 0.03) * path
        r40 = closes[s][-1] / closes[s][-41] - 1.0
        worst40 = np.minimum(r[-40:], 0.0)
        tail = r40 / max(np.sqrt(np.sum(worst40 ** 2)), 0.03)
        values = {
            "miner_1_20280810_relative_reversal_5d": -(five[s] - med5) / sd10,
            "miner_1_20290517_stress_residual_reversal": -np.mean(residual) / sd10 if stress else 0.0,
            "miner_3_20290503_stress_downside_reversal_10d": -(np.mean(neg20) if len(neg20) else 0.0) / sd10 if stress else 0.0,
            "miner_3_20290405_extreme_breadth_reversal_5d": -(five[s] - med5) / sd10 if breadth < 0.35 else 0.0,
            "miner_3_20290222_vix_gated_relative_reversal": -(five[s] - med5) / sd10 if vix else 0.0,
            "miner_2_20290906_regime_neutral_reversal_10d": -(ten[s] - med10) / sd10,
            "miner_3_20290823_risk_adjusted_momentum_reversal_10d": -(closes[s][-11] / closes[s][-41] - 1.0) / max(sd60 * 10.0, 0.02),
            "miner_3_20291129_inverse_trend_quality_10d": inverse_tq,
        }
        raw[s] = {fid: values.get(fid, 0.0) for fid in factor_ids}

    ranked = {fid: rank_cs({s: raw[s][fid] for s in closes}) for fid in factor_ids}
    score = {s: sum(coef[fid] * ranked[fid][s] for fid in factor_ids) for s in closes}
    if stress:
        for s in ("XAU", "US10Y", "CN10Y"):
            if s in score: score[s] += 0.10
        for s in ("BTC", "ETH", "WTI"):
            if s in score: score[s] -= 0.05
    if bear:
        for s in ("XAU", "US10Y", "CN10Y"):
            if s in score: score[s] += 0.12
        for s in ("BTC", "ETH", "WTI", "SOX", "NDX"):
            if s in score: score[s] -= 0.06

    # Small exponential tilt plus a floor; missing assets receive the neutral floor.
    arr = np.array([score.get(s, np.mean(list(score.values()))) for s in ASSETS])
    z = (arr - arr.mean()) / max(arr.std(), 1e-9)
    weights = np.maximum(np.exp(np.clip(0.12 * z, -0.55, 0.55)), 0.015)
    weights /= weights.sum()
    target = {s: float(weights[i]) for i, s in enumerate(ASSETS)}
    forecast = {s: float(0.01 * z[i]) for i, s in enumerate(ASSETS)}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)

