import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factor_ensemble.json"
_calls = 0

def cs_rank(values):
    good = sorted((k, float(v)) for k, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in ASSETS}
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.0) / max(len(good), 1)
    return out

def vix_is_high():
    try:
        d = get_index_daily_data("VIX", 65)
        x = np.asarray(d.sort_values("date")["close"], float)
        return len(x) >= 61 and x[-1] > np.median(x[-61:-1])
    except Exception:
        return False

@register_hook
def strategy():
    global _calls
    if _calls % 10 != 0:
        _calls += 1
        return
    _calls += 1
    try:
        selected = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not selected or abs(sum(float(f["weight"]) for f in selected) - 1.0) > 1e-5:
        return
    ids = [str(f["factor_id"]) for f in selected]
    closes = {}
    for s in ASSETS:
        d = get_stock_daily_data(symbol=s, days=230)
        if d is not None and len(d) >= 70:
            c = np.asarray(d.sort_values("date")["close"], float)
            if np.all(np.isfinite(c)) and np.all(c > 0): closes[s] = c
    if len(closes) < 12: return
    returns = {s: c[1:] / c[:-1] - 1.0 for s, c in closes.items()}
    med5 = np.median([np.mean(r[-5:]) for r in returns.values()])
    breadth = np.mean([np.mean(r[-5:]) > 0 for r in returns.values()])
    market = np.mean(np.vstack([r[-60:] for r in returns.values()]), axis=0)
    vix = vix_is_high()
    stress = vix or breadth < 0.45
    raw = {s: {} for s in closes}
    for s, r in returns.items():
        sd10 = max(np.std(r[-10:], ddof=1), 0.008)
        sd20 = max(np.std(r[-20:], ddof=1), 0.008)
        sd60 = max(np.std(r[-60:], ddof=1), 0.008)
        beta = np.cov(r[-60:], market)[0, 1] / max(np.var(market), 1e-9)
        resid = r[-5:] - beta * market[-5:]
        neg = r[-20:][r[-20:] < 0]
        r40 = closes[s][-1] / closes[s][-41] - 1.0
        downside = np.sqrt(np.sum(np.minimum(r[-40:], 0.0) ** 2))
        vals = {
            "stress_residual_reversal": -np.mean(resid) / sd10 if stress else 0.0,
            "relative_reversal": -(np.mean(r[-5:]) - med5) / sd10,
            "vix_gated_relative_reversal": -(np.mean(r[-5:]) - med5) / sd10 if vix else 0.0,
            "stress_downside_reversal": -(np.mean(neg) if len(neg) else 0.0) / sd10 if stress else 0.0,
            "extreme_breadth_reversal": -(np.mean(r[-5:]) - med5) / sd10 if breadth < 0.35 else 0.0,
            "regime_neutral_reversal": -(np.mean(r[-10:]) - np.median([np.mean(x[-10:]) for x in returns.values()])) / sd20,
            "volume_confirmed_reversal": -(np.mean(r[-5:]) - med5) / sd20,
            "tail_resilience": r40 / max(downside, 0.03),
        }
        for fid in ids:
            key = next((k for k in vals if k in fid), None)
            raw[s][fid] = vals.get(key, 0.0)
    score = {s: sum(float(f["weight"]) * int(f.get("direction", 1)) * cs_rank({a: raw[a][fid] for a in closes})[s] for f, fid in zip(selected, ids)) for s in closes}
    if stress:
        for s in ("XAU", "US10Y", "CN10Y"): score[s] = score.get(s, .5) + 0.10
        for s in ("BTC", "ETH", "WTI"): score[s] = score.get(s, .5) - 0.05
    arr = np.array([score.get(s, 0.5) for s in ASSETS], dtype=float)
    z = (arr - arr.mean()) / max(arr.std(), 1e-9)
    weights = np.maximum(np.exp(np.clip(0.14 * z, -0.55, 0.55)), 0.015)
    weights /= weights.sum()
    target = {s: float(weights[i]) for i, s in enumerate(ASSETS)}
    forecast = {s: float(0.01 * z[i]) for i, s in enumerate(ASSETS)}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)

