ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factor_ensemble.json"
_calls = 0


def cs_rank(values):
    good = sorted((a, v) for a, v in values.items() if np.isfinite(v))
    out = {a: 0.5 for a in ASSETS}
    if not good:
        return out
    for i, (a, _) in enumerate(good):
        out[a] = (i + 1.0) / len(good)
    return out


def elevated_vix():
    try:
        d = get_index_daily_data("VIX", 65)
        x = np.asarray(d.sort_values("date")["close"], dtype=float)
        return len(x) >= 61 and x[-1] > np.median(x[-61:-1])
    except Exception:
        return False


@register_hook
def strategy():
    global _calls
    if _calls % 10:
        _calls += 1
        return
    _calls += 1
    try:
        factors = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not factors or abs(sum(float(f["weight"]) for f in factors) - 1.0) > 1e-5:
        return
    factor_ids = [str(f["factor_id"]) for f in factors]
    close = {}
    for a in ASSETS:
        d = get_stock_daily_data(symbol=a, days=230)
        if d is None or len(d) < 70:
            continue
        c = np.asarray(d.sort_values("date")["close"], dtype=float)
        if len(c) >= 70 and np.all(np.isfinite(c)) and np.all(c > 0):
            close[a] = c
    if len(close) < 12:
        return
    n = min(map(len, close.values()))
    close = {a: c[-n:] for a, c in close.items()}
    returns = {a: c[1:] / c[:-1] - 1.0 for a, c in close.items()}
    market = np.mean(np.vstack([r[-60:] for r in returns.values()]), axis=0)
    med5 = np.median([np.mean(r[-5:]) for r in returns.values()])
    med40 = np.median([c[-1] / c[-41] - 1.0 for c in close.values()])
    breadth = np.mean([np.mean(r[-5:]) > 0 for r in returns.values()])
    vix = elevated_vix()
    stress = bool(vix or breadth < 0.45)

    score_raw = {a: {} for a in close}
    for a, r in returns.items():
        sd10 = max(float(np.std(r[-10:], ddof=1)), 0.008)
        sd20 = max(float(np.std(r[-20:], ddof=1)), 0.008)
        sd40 = max(float(np.std(r[-40:], ddof=1)), 0.008)
        beta = float(np.cov(r[-60:], market)[0, 1] / max(np.var(market), 1e-9))
        resid = r[-5:] - beta * market[-5:]
        neg = r[-20:][r[-20:] < 0]
        vals = {
            "stress_residual_reversal": -np.mean(resid) / sd10 if stress else 0.0,
            "stress_downside_reversal": -(np.mean(neg) if len(neg) else 0.0) / sd10 if stress else 0.0,
            "vix_gated_relative_reversal": -(np.mean(r[-5:]) - med5) / sd10 if vix else 0.0,
            "volscaled_relative_reversal": -(c[-1] / c[-41] - 1.0 - med40) / sd40,
            "extreme_breadth_reversal": -(np.mean(r[-5:]) - med5) / sd10 if breadth < 0.35 else 0.0,
            "volume_confirmed_reversal": -(np.mean(r[-5:]) - med5) / sd20,
            "relative_reversal": -(np.mean(r[-5:]) - med5) / sd10,
            "lowvix_volscaled_trend": (c[-1] / c[-31] - 1.0) / sd20 if not vix else 0.0,
        }
        for fid in factor_ids:
            key = next((k for k in vals if k in fid), None)
            score_raw[a][fid] = vals.get(key, 0.0)

    score = {a: 0.0 for a in ASSETS}
    for f in factors:
