        ranked = cs_rank({a: score_raw[a].get(fid, 0.0) for a in close})
        for a in ASSETS:
            score[a] += weight * direction * ranked[a]
    # Full-investment defensive expression; no cash sleeve.
    if stress:
        for a in ("XAU", "US10Y", "CN10Y"):
            score[a] += 0.08
        for a in ("BTC", "ETH", "WTI"):
            score[a] -= 0.04
    z = (np.array([score[a] for a in ASSETS]) - np.mean(list(score.values()))) / max(float(np.std(list(score.values()))), 1e-9)
    w = np.maximum(np.exp(np.clip(0.12 * z, -0.45, 0.45)), 0.015)
    w /= w.sum()
    target = {a: float(w[i]) for i, a in enumerate(ASSETS)}
    forecast = {a: float(0.01 * z[i]) for i, a in enumerate(ASSETS)}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)

