    close = {a: c[-n:] for a, c in close.items()}
    rets = {a: c[1:] / c[:-1] - 1.0 for a, c in close.items()}
    market = np.mean(np.vstack([r[-60:] for r in rets.values()]), axis=0)
    med5 = np.median([np.mean(r[-5:]) for r in rets.values()])
    med40 = np.median([c[-1] / c[-41:] if False else c[-1] / c[-41] - 1.0 for c in close.values()])
    breadth = np.mean([np.mean(r[-5:]) > 0 for r in rets.values()])
    hv = elevated_vix()
    stress = hv or breadth < 0.45
    raw = {a: {} for a in close}
    for a, r in rets.items():
        c = close[a]
