import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
_calls = 0

def cs_rank(x):
    good = sorted((v, a) for a, v in x.items() if np.isfinite(v))
    out = {a: .5 for a in ASSETS}
    for i, (_, a) in enumerate(good):
        out[a] = (i + 1) / max(len(good), 1)
    return out

def vix_high():
    try:
        d = get_index_daily_data("VIX", 70)
        x = np.asarray(d.sort_values("date")["close"], float)
        return len(x) >= 62 and x[-1] > np.median(x[-61:-1])
    except Exception:
        return False

@register_hook
def strategy():
    global _calls
    if _calls % 10:
        _calls += 1
        return
    _calls += 1
    try:
        factors = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not factors or abs(sum(float(f.get("weight", 0)) for f in factors) - 1) > 1e-5:
        return
    ids = [str(f["factor_id"]) for f in factors]
    px = {}
    for a in ASSETS:
        d = get_stock_daily_data(symbol=a, days=250)
        if d is not None and len(d) >= 100:
            c = np.asarray(d.sort_values("date")["close"], float)[:-1]
            if len(c) >= 70 and np.all(np.isfinite(c)) and np.all(c > 0):
                px[a] = c
    if len(px) < 12:
        return
    n = min(map(len, px.values()))
    px = {a: c[-n:] for a, c in px.items()}
    rr = {a: c[1:] / c[:-1] - 1 for a, c in px.items()}
    market = np.mean(np.array([r[-60:] for r in rr.values()]), axis=0)
    med5 = np.median([np.mean(r[-5:]) for r in rr.values()])
