    # benchmarks receive the tilt instead of a cash sleeve.
    if stressed:
        for a in ("XAU", "US10Y", "CN10Y"):
            score[a] += 0.12
        for a in ("BTC", "ETH", "WTI"):
            score[a] -= 0.06

    z = {a: (score[a] - np.mean(list(score.values()))) / max(np.std(list(score.values())), 1e-9) for a in ASSETS}
    # Broad, low-concentration allocation is appropriate for a 15-name universe.
    weights = np.array([max(np.exp(np.clip(0.07 * z[a], -.30, .30)), .025) for a in ASSETS])
    weights /= weights.sum()
    target = {a: float(weights[i]) for i, a in enumerate(ASSETS)}
    forecast = {a: float(0.006 * z[a]) for a in ASSETS}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)

