ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
_calls = 0

def ranks(d):
    out = {a: 0.5 for a in ASSETS}
    good = sorted((float(v), a) for a, v in d.items() if np.isfinite(v))
    for i, (_, a) in enumerate(good):
        out[a] = (i + 1.0) / len(good)
    return out

def high_vix():
    try:
        d = get_index_daily_data("VIX", 70)
        x = np.asarray(d.sort_values("date")["close"], float)
        return len(x) >= 61 and x[-1] > np.median(x[-61:-1])
    except Exception:
        return False

@register_hook
def strategy():
    global _calls
    if _calls % 10:
        _calls += 1
        return
    _calls += 1
    try:
        factors = json.loads(ENSEMBLE.read_text())["selected_factors"][:10]
    except Exception:
        return
    if not factors or abs(sum(float(f["weight"]) for f in factors) - 1.0) > 1e-5:
        return
    factor_ids = [str(f["factor_id"]) for f in factors]
    prices = {}
    for a in ASSETS:
        d = get_stock_daily_data(symbol=a, days=260)
        if d is None or len(d) < 90:
            continue
        c = np.asarray(d.sort_values("date")["close"], float)
        # Decisions use the last completed observation only.
        c = c[:-1]
        if len(c) >= 80 and np.all(np.isfinite(c)) and np.all(c > 0):
            prices[a] = c[-180:]
    if len(prices) < 12:
        return
    n = min(map(len, prices.values()))
    prices = {a: c[-n:] for a, c in prices.items()}
    rets = {a: c[1:] / c[:-1] - 1.0 for a, c in prices.items()}
    market = np.mean([r[-60:] for r in rets.values()], axis=0)
