ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
_calls = 0


def percentile(values):
    good = {a: float(v) for a, v in values.items() if np.isfinite(v)}
    if not good:
        return {a: .5 for a in ASSETS}
    ordered = sorted(good, key=good.get)
    out = {a: .5 for a in ASSETS}
    for i, a in enumerate(ordered):
        out[a] = (i + 1.0) / len(ordered)
    return out


def high_vix():
    try:
        d = get_index_daily_data("VIX", 70)
        x = np.asarray(d.sort_values("date")["close"], float)
        return len(x) >= 62 and x[-1] > np.median(x[-61:-1])
    except Exception:
        return False


@register_hook
def strategy():
    global _calls
    if _calls % 10:
        _calls += 1
        return
    _calls += 1
    try:
        fs = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not fs or abs(sum(float(f["weight"]) for f in fs) - 1.0) > 1e-5:
        return
    factor_ids = [str(f["factor_id"]) for f in fs]
    px = {}
    for a in ASSETS:
        d = get_stock_daily_data(symbol=a, days=260)
        if d is None or len(d) < 95:
            continue
        c = np.asarray(d.sort_values("date")["close"], float)[:-1]
        if len(c) >= 80 and np.all(np.isfinite(c)) and np.all(c > 0):
            px[a] = c[-180:]
    if len(px) < 12:
        return
    n = min(len(x) for x in px.values())
    px = {a: x[-n:] for a, x in px.items()}
    ret = {a: x[1:] / x[:-1] - 1 for a, x in px.items()}
    market = np.mean([x[-60:] for x in ret.values()], axis=0)
    med60 = np.median([x[-1] / x[-61] - 1 for x in px.values()])
    med10 = np.median([np.mean(x[-10:]) for x in ret.values()])
    risky = high_vix() or np.mean([np.mean(x[-10:]) > 0 for x in ret.values()]) < .45
    raw = {a: {} for a in px}
    for a, c in px.items():
        r = ret[a]
        v10 = max(np.std(r[-10:], ddof=1), .008)
        v30 = max(np.std(r[-30:], ddof=1), .008)
        v60 = max(np.std(r[-60:], ddof=1), .008)
        neg = r[-60:][r[-60:] < 0]
        down = max(np.std(neg, ddof=1) if len(neg) > 1 else .008, .008)
        r10 = c[-1] / c[-11] - 1
        r60 = c[-1] / c[-61] - 1
        beta = np.cov(r[-60:], market)[0, 1] / max(np.var(market), 1e-9)
        residual = np.sum(r[-10:] - beta * market[-10:])
        raw[a] = {
            "relative_strength_reversal_volscaled": -(r60 - med60) / v60,
            "medium_reversal_downside_scaled": -r60 / down,
            "downside_skew_reversal": -r10 / down,
            "relative_momentum_reversal": -(r60 - med60) / v60,
            "vix_gated_relative_reversal": -((np.mean(r[-5:]) - med10) / v10) if risky else 0.0,
            "volatility_dispersion": -(v30 / v60 - 1),
            "defensive_trend_quality": r60 / v60,
            "stress_residual_reversal": -residual / v10,
        }
    scores = {a: 0.0 for a in ASSETS}
    for f in fs:
        fid = str(f["factor_id"])
        key = next((k for k in raw[next(iter(raw))] if k in fid), None)
        if key is None:
            continue
        ranks = percentile({a: raw[a][key] for a in px})
        for a in ASSETS:
            scores[a] += float(f["weight"]) * int(f.get("direction", 1)) * ranks[a]
    if risky:
        for a in ("XAU", "US10Y", "CN10Y"):
            scores[a] += .12
        for a in ("BTC", "ETH", "WTI"):
            scores[a] -= .06
    z = np.array([scores[a] for a in ASSETS], float)
    z = (z - z.mean()) / max(z.std(), 1e-9)
    w = np.maximum(np.exp(.07 * np.clip(z, -.30, .30)), .025)
    w /= w.sum()
    target = {a: float(w[i]) for i, a in enumerate(ASSETS)}
    forecast = {a: float(.006 * z[i]) for i, a in enumerate(ASSETS)}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)

