ENSEMBLE = Path(__file__).parent / "factor_ensemble.json"
_calls = 0

def rank(values):
    out = {a: 0.5 for a in ASSETS}
    good = sorted([(a, float(v)) for a, v in values.items() if np.isfinite(v)], key=lambda x: x[1])
    if good:
        for i, (a, _) in enumerate(good): out[a] = (i + 1.0) / len(good)
    return out

def vix_stressed():
    try:
        d = get_index_daily_data("VIX", 70)
        v = np.asarray(d.sort_values("date")["close"], float)
        return len(v) >= 62 and v[-1] > np.median(v[-61:-1])
    except Exception:
        return False

@register_hook
def strategy():
    global _calls
    if _calls % 10:
        _calls += 1
