import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factor_ensemble.json"
_calls = 0


def rank(values):
    out = {a: 0.5 for a in ASSETS}
    good = sorted((a, float(v)) for a, v in values.items() if np.isfinite(v))
    if good:
        for i, (a, _) in enumerate(good):
            out[a] = (i + 1.0) / len(good)
    return out


def high_stress():
    try:
        d = get_index_daily_data("VIX", 70)
        v = np.asarray(d.sort_values("date")["close"], float)
        return len(v) >= 62 and v[-1] > np.median(v[-61:-1])
    except Exception:
        return False


@register_hook
def strategy():
    global _calls
    if _calls % 10 != 0:
        _calls += 1
        return
    _calls += 1
    try:
        factors = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not factors or abs(sum(float(f.get("weight", 0.0)) for f in factors) - 1.0) > 1e-5:
        return

    data = {}
    for a in ASSETS:
        d = get_stock_daily_data(symbol=a, days=270)
        if d is None or len(d) < 130:
            continue
        c = np.asarray(d.sort_values("date").iloc[:-1]["close"], float)
        if len(c) >= 100 and np.all(np.isfinite(c)) and np.all(c > 0):
            data[a] = c[-200:]
    if len(data) < 12:
        return
    n = min(len(x) for x in data.values())
    data = {a: c[-n:] for a, c in data.items()}
    rets = {a: np.diff(c) / c[:-1] for a, c in data.items()}
    cross10 = float(np.median([np.mean(r[-10:]) for r in rets.values()]))
    breadth = float(np.mean([np.mean(r[-10:]) > 0 for r in rets.values()]))
    raw = {a: {} for a in data}
    for a, c in data.items():
        r = rets[a]
        v20 = max(float(np.std(r[-20:], ddof=1)), .008)
        v30 = max(float(np.std(r[-30:], ddof=1)), .008)
        v60 = max(float(np.std(r[-60:], ddof=1)), .008)
        ret20 = c[-1] / c[-21] - 1.0
        ret60 = c[-1] / c[-61] - 1.0
        path = max(float(np.sum(np.abs(r[-60:]))), 1e-12)
        raw[a] = {
            "riskadjusted_momentum": ret60 / v60,
            "efficiency_reversal": -(ret60 / path) / v20,
            "compressed_trend_reversal": -ret60 / v60 * np.clip(v60 / v20, .5, 2.0),
            "breadth_gated_contrarian": (-(np.mean(r[-10:]) - cross10) / v20) if breadth < .60 else 0.0,
            "relative_strength_reversal_volscaled": -(ret20 - 2.0 * cross10) / v20,
            "range_stressed_reversal": -ret20 / v30,
            "volatility_dispersion": -(v30 / v60 - 1.0),
        }

    aliases = {
        "riskadjusted_momentum": "riskadjusted_momentum",
        "efficiency_reversal": "efficiency_reversal",
        "compressed_trend_reversal": "compressed_trend_reversal",
        "breadth_gated_contrarian": "breadth_gated_contrarian",
        "relative_strength_reversal_volscaled": "relative_strength_reversal_volscaled",
        "range_stressed_reversal": "range_stressed_reversal",
        "volatility_dispersion": "volatility_dispersion",
    }
    scores = {a: 0.0 for a in ASSETS}
    factor_ids = []
    for f in factors:
        fid = str(f.get("factor_id", ""))
        key = next((k for k in aliases if k in fid), None)
        if key is None:
            return
        factor_ids.append(fid)
        rr = rank({a: raw[a][key] for a in data})
        for a in ASSETS:
            scores[a] += float(f["weight"]) * int(f.get("direction", 1)) * rr[a]

    if high_stress() or breadth < .45:
        for a in ("XAU", "US10Y", "CN10Y"):
            scores[a] += .12
        for a in ("BTC", "ETH", "WTI"):
            scores[a] -= .06
    z = np.array([scores[a] for a in ASSETS], dtype=float)
    z = (z - z.mean()) / max(float(z.std()), 1e-9)
    w = np.maximum(np.exp(.07 * np.clip(z, -.30, .30)), .025)
    w /= w.sum()
    target = {a: float(w[i]) for i, a in enumerate(ASSETS)}
    forecast = {a: float(.006 * z[i]) for i, a in enumerate(ASSETS)}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)

