ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
_calls = 0


def ranks(values):
    out = {a: 0.5 for a in ASSETS}
    good = sorted((a, float(v)) for a, v in values.items() if np.isfinite(v))
    for i, (a, _) in enumerate(good):
        out[a] = (i + 1.0) / len(good)
    return out


def stressed():
    try:
        d = get_index_daily_data("VIX", 70)
        v = np.asarray(d.sort_values("date")["close"], float)
        return len(v) >= 62 and v[-1] > np.median(v[-61:-1])
    except Exception:
        return False


@register_hook
def strategy():
    global _calls
    if _calls % 10:
        _calls += 1
        return
    _calls += 1
    try:
        factors = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not factors or abs(sum(float(f.get("weight", 0)) for f in factors) - 1) > 1e-5:
        return

    data = {}
    for a in ASSETS:
        d = get_stock_daily_data(symbol=a, days=270)
        if d is None or len(d) < 130:
            continue
        c = np.asarray(d.sort_values("date").iloc[:-1]["close"], float)
        if len(c) >= 100 and np.all(np.isfinite(c)) and np.all(c > 0):
            data[a] = c[-200:]
    if len(data) < 12:
        return
    n = min(map(len, data.values()))
    data = {a: c[-n:] for a, c in data.items()}
    rets = {a: np.diff(c) / c[:-1] for a, c in data.items()}
    median10 = float(np.median([np.mean(r[-10:]) for r in rets.values()]))
    breadth = float(np.mean([np.mean(r[-10:]) > 0 for r in rets.values()]))
    raw = {a: {} for a in data}
    for a, c in data.items():
        r = rets[a]
        v20 = max(float(np.std(r[-20:], ddof=1)), .008)
        v30 = max(float(np.std(r[-30:], ddof=1)), .008)
        v60 = max(float(np.std(r[-60:], ddof=1)), .008)
        ret20, ret60 = c[-1] / c[-21] - 1, c[-1] / c[-61] - 1
        path = max(float(np.sum(np.abs(r[-60:]))), 1e-12)
        raw[a] = {
            "riskadjusted_momentum": ret60 / v60,
            "efficiency_reversal": -(ret60 / path) / v20,
            "compressed_trend_reversal": -ret60 / v60 * np.clip(v60 / v20, .5, 2),
            "long_gap": -(ret20 - median10) / v20,
            "breadth_gated_contrarian": (-(np.mean(r[-10:]) - median10) / v20) if breadth < .60 else 0,
            "relative_strength_reversal": -(ret20 - 2 * median10) / v20,
            "range_stressed_reversal": -ret20 / v30,
            "volatility_dispersion": -(v30 / v60 - 1),
        }
    aliases = {
        "riskadjusted_momentum": "riskadjusted_momentum", "efficiency_reversal": "efficiency_reversal",
        "compressed_trend_reversal": "compressed_trend_reversal", "long_gap_volscaled": "long_gap",
        "breadth_gated_contrarian": "breadth_gated_contrarian", "relative_strength_reversal_volscaled": "relative_strength_reversal",
        "range_stressed_reversal": "range_stressed_reversal", "volatility_dispersion": "volatility_dispersion"
    }
    scores = {a: 0.0 for a in ASSETS}
