    for f in factors:
        fid = str(f.get("factor_id", "")); key = next((k for k in aliases if k in fid), None)
        if key is None: return
        factor_ids.append(fid)
        rr = ranks({a: raw[a][aliases[key]] for a in data})
        for a in ASSETS:
            scores[a] += float(f["weight"]) * int(f.get("direction", 1)) * rr[a]
    if stressed() or breadth < .45:
        for a in ("XAU", "US10Y", "CN10Y"): scores[a] += .12
        for a in ("BTC", "ETH", "WTI"): scores[a] -= .06
