import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
_calls = 0


def rank_cs(values):
    out = {a: 0.5 for a in ASSETS}
    valid = sorted((a, float(v)) for a, v in values.items() if np.isfinite(v))
    for i, (a, _) in enumerate(valid):
        out[a] = (i + 1.0) / len(valid)
    return out


def high_risk():
    try:
        d = get_index_daily_data("VIX", 70)
        v = np.asarray(d.sort_values("date")["close"], dtype=float)
        return len(v) >= 62 and v[-1] > np.median(v[-61:-1])
    except Exception:
        return False


@register_hook
def strategy():
    global _calls
    if _calls % 10 != 0:
        _calls += 1
        return
    _calls += 1
    try:
        fs = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not fs or abs(sum(float(f.get("weight", 0.0)) for f in fs) - 1.0) > 1e-5:
        return

    prices = {}
    for a in ASSETS:
        d = get_stock_daily_data(symbol=a, days=270)
        if d is None or len(d) < 140:
            continue
        c = np.asarray(d.sort_values("date").iloc[:-1]["close"], dtype=float)
        if len(c) >= 130 and np.all(np.isfinite(c)) and np.all(c > 0):
            prices[a] = c[-220:]
    if len(prices) < 12:
        return
    n = min(len(c) for c in prices.values())
    prices = {a: c[-n:] for a, c in prices.items()}
    rets = {a: np.diff(c) / c[:-1] for a, c in prices.items()}
    matrix = np.array(list(rets.values()))
    breadth20 = float(np.mean(np.mean(matrix[:, -20:], axis=1) > 0))
    median_daily = np.median(matrix, axis=0)
    median_vol20 = max(float(np.median([np.std(r[-20:], ddof=1) for r in rets.values()])), .008)

    raw = {a: {} for a in prices}
    for a, c in prices.items():
        r = rets[a]
        v20 = max(float(np.std(r[-20:], ddof=1)), .008)
        v40 = max(float(np.std(r[-40:], ddof=1)), .008)
        v60 = max(float(np.std(r[-60:], ddof=1)), .008)
        # Factor implementations use only completed, lagged observations.
        raw[a]["riskadjusted_momentum"] = (c[-1] / c[-121] - 1.0) / v60
        path = max(float(np.sum(np.abs(r[-40:]))), 1e-9)
        raw[a]["defensive_trend_quality"] = ((c[-1] / c[-61] - 1.0) / v40) * (abs(float(np.sum(r[-40:]))) / path)
        high = np.maximum.accumulate(c[-61:])
        raw[a]["breadth_conditioned_duration"] = float(np.sum(c[-61:] < high)) / v20 * (2.0 - breadth20)
        excess = r[-40:] - median_daily[-40:]
        downside = np.minimum(excess, 0.0)
        raw[a]["downside_stability_reversal"] = -float(np.sum(excess)) / v40 / (1.0 + float(np.std(downside, ddof=1)) / v40)
        raw[a]["volatility_dispersion"] = -(v20 / median_vol20 - 1.0)

    aliases = {
        "riskadjusted_momentum": "riskadjusted_momentum",
        "defensive_trend_quality": "defensive_trend_quality",
        "breadth_conditioned_duration": "breadth_conditioned_duration",
        "downside_stability_reversal": "downside_stability_reversal",
        "volatility_dispersion": "volatility_dispersion",
    }
    score = {a: 0.0 for a in ASSETS}
    factor_ids = []
    for f in fs:
        fid = str(f.get("factor_id", ""))
        key = next((k for k in aliases if k in fid), None)
        if key is None:
            return
        factor_ids.append(fid)
        ranks = rank_cs({a: raw[a][key] for a in raw})
        for a in ASSETS:
            score[a] += float(f["weight"]) * int(f.get("direction", 1)) * ranks[a]

    # Bear/high-volatility posture: full investment remains in defensive tradables.
    if high_risk() or breadth20 < 0.45:
        for a in ("XAU", "US10Y", "CN10Y"):
            score[a] += 0.12
        for a in ("BTC", "ETH", "WTI"):
            score[a] -= 0.06

    z = np.array([score[a] for a in ASSETS], dtype=float)
    z = (z - z.mean()) / max(float(z.std()), 1e-9)
    weights = np.maximum(np.exp(0.10 * np.clip(z, -1.5, 1.5)), 0.025)
    weights /= weights.sum()
    target = {a: float(weights[i]) for i, a in enumerate(ASSETS)}
    forecast = {a: float(0.006 * z[i]) for i, a in enumerate(ASSETS)}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)

