ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
_calls = 0

def percentile(values):
    good = sorted((a, float(v)) for a, v in values.items() if np.isfinite(v))
    out = {a: .5 for a in ASSETS}
    for i, (a, _) in enumerate(good):
        out[a] = (i + 1.0) / len(good) if good else .5
    return out

def stress_signal():
    try:
        d = get_index_daily_data("VIX", 70)
        v = np.asarray(d.sort_values("date")["close"], float)
        return len(v) >= 25 and v[-1] > np.median(v[-25:-1])
    except Exception:
        return False

@register_hook
def strategy():
    global _calls
    if _calls % 10:
        _calls += 1
        return
    _calls += 1
    try:
        selected = json.loads(ENSEMBLE.read_text())["selected_factors"][:10]
    except Exception:
        return
    if not selected or abs(sum(float(x["weight"]) for x in selected) - 1) > 1e-5:
        return

    px = {}
    for a in ASSETS:
        d = get_stock_daily_data(symbol=a, days=280)
        if d is None or len(d) < 150:
            continue
        c = np.asarray(d.sort_values("date").iloc[:-1]["close"], float)
        if len(c) >= 130 and np.all(np.isfinite(c)) and np.all(c > 0):
            px[a] = c[-220:]
    if len(px) < 12:
        return
    n = min(map(len, px.values()))
    px = {a: c[-n:] for a, c in px.items()}
    rr = {a: np.diff(c) / c[:-1] for a, c in px.items()}
    breadth = float(np.mean([np.mean(r[-20:] > 0) for r in rr.values()]))
    medvol = max(float(np.median([np.std(r[-20:], ddof=1) for r in rr.values()])), .008)
    raw = {a: {} for a in px}
    for a, c in px.items():
        r = rr[a]
        v20 = max(float(np.std(r[-20:], ddof=1)), .008)
        v40 = max(float(np.std(r[-40:], ddof=1)), .008)
        v60 = max(float(np.std(r[-60:], ddof=1)), .008)
        ret60 = c[-1] / c[-61] - 1
