            "miner_2_20301212_efficiency_reversal_60d": -ret60 / path / v20,
            "miner_3_20310724_quadratic_breadth_reversal_60d": (-ret60 / v60) * (2-breadth)**2,
            "miner_3_20310710_breadth_gated_reversal_60d": (-ret60 / v60) * (2-breadth),
            "miner_2_20300822_defensive_trend_quality_60d": (ret60 / v40) * (abs(np.sum(r[-40:])) / max(np.sum(np.abs(r[-40:])), 1e-8)),
            "miner_1_20300627_downside_stability_reversal_60d": -ret60 / downside * (1-min(dd, .8)),
            "miner_3_20300822_volatility_dispersion_60d": -(v20 / medvol - 1),
