ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
_calls = 0

def pct_rank(x):
    good = sorted((a, float(v)) for a, v in x.items() if np.isfinite(v))
    out = {a: 0.5 for a in ASSETS}
    for i, (a, _) in enumerate(good):
        out[a] = (i + 1.0) / len(good)
    return out

def stressed():
    try:
        d = get_index_daily_data("VIX", 70)
        v = np.asarray(d.sort_values("date")["close"], float)
        return len(v) >= 25 and v[-1] > np.median(v[-25:-1])
    except Exception:
        return False

@register_hook
def strategy():
    global _calls
    if _calls % 10:
        _calls += 1
        return
    _calls += 1
    try:
        selected = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not selected or abs(sum(float(f["weight"]) for f in selected) - 1.0) > 1e-5:
        return
    px = {}
    for a in ASSETS:
        d = get_stock_daily_data(symbol=a, days=280)
        if d is None or len(d) < 150:
            continue
        c = np.asarray(d.sort_values("date").iloc[:-1]["close"], float)
        if len(c) >= 130 and np.all(np.isfinite(c)) and np.all(c > 0):
            px[a] = c[-220:]
    if len(px) < 12:
        return
    n = min(len(v) for v in px.values())
    px = {a: v[-n:] for a, v in px.items()}
    ret = {a: np.diff(v) / v[:-1] for a, v in px.items()}
    breadth = float(np.mean([np.mean(r[-20:] > 0) for r in ret.values()]))
    medvol = max(float(np.median([np.std(r[-20:], ddof=1) for r in ret.values()])), .008)
    raw = {a: {} for a in px}
    for a, c in px.items():
        r = ret[a]
        v20 = max(float(np.std(r[-20:], ddof=1)), .008)
        v40 = max(float(np.std(r[-40:], ddof=1)), .008)
        v60 = max(float(np.std(r[-60:], ddof=1)), .008)
        ret20, ret60 = c[-1] / c[-21] - 1, c[-1] / c[-61] - 1
        path = max(float(np.sum(np.abs(r[-60:]))), 1e-8)
        downside = max(float(np.std(np.minimum(r[-60:], 0), ddof=1)), .004)
        peak = np.maximum.accumulate(c[-61:])
        dd = abs(float(np.min(c[-61:] / peak - 1)))
        raw[a] = {
            "miner_1_20301031_riskadjusted_momentum_60d": ret60 / v60,
            "miner_2_20301114_compressed_trend_reversal_60d": (-ret60 / v60) * (1.0 + min(v40 / v20, 2.0)),
            "miner_2_20301212_efficiency_reversal_60d": -ret60 / path / v20,
            "miner_3_20301128_range_stressed_reversal_60d": (-ret20 / v20) * (1.0 + min(dd, .5)),
            "miner_1_20310821_choppy_residual_reversal_60d": 0.0,
            "miner_2_20300822_defensive_trend_quality_60d": (ret60 / v40) * (abs(np.sum(r[-40:])) / max(np.sum(np.abs(r[-40:])), 1e-8)),
            "miner_1_20300627_downside_stability_reversal_60d": -ret60 / downside * (1.0 - min(dd, .8)),
            "miner_3_20300822_volatility_dispersion_60d": -(v20 / medvol - 1.0),
        }
    # Cross-sectional residual reversal, damped by path choppiness.
    mean60 = float(np.mean([c[-1] / c[-61] - 1 for c in px.values()]))
    for a, c in px.items():
        r = ret[a]
        residual = (c[-1] / c[-61] - 1) - mean60
        chop = min(float(np.sum(np.abs(r[-60:])) / max(abs(np.sum(r[-60:])), .01)), 4.0)
        raw[a]["miner_1_20310821_choppy_residual_reversal_60d"] = -residual * (0.75 + 0.0625 * chop)
    score = {a: 0.0 for a in ASSETS}
    factor_ids = []
    for f in selected:
        fid, direction = str(f["factor_id"]), int(f.get("direction", 1))
        if fid not in raw[next(iter(raw))]:
            return
        factor_ids.append(fid)
        ranks = pct_rank({a: raw[a][fid] for a in raw})
        for a in ASSETS:
            score[a] += float(f["weight"]) * direction * ranks[a]
    if stressed() or breadth < .45:
        for a in ("XAU", "US10Y", "CN10Y"): score[a] += .12
        for a in ("BTC", "ETH", "WTI"): score[a] -= .06
    vals = np.array([score[a] for a in ASSETS])
    z = (vals - vals.mean()) / max(float(vals.std()), 1e-9)
    w = np.maximum(np.exp(.10 * np.clip(z, -1.5, 1.5)), .025)
    w /= w.sum()
    target = {a: float(w[i]) for i, a in enumerate(ASSETS)}
    forecast = {a: float(.006 * z[i]) for i, a in enumerate(ASSETS)}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)

