import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
_calls = 0


def ranks(values):
    valid = sorted((a, float(v)) for a, v in values.items() if np.isfinite(v))
    out = {a: 0.5 for a in ASSETS}
    for i, (asset, _) in enumerate(valid):
        out[asset] = (i + 1.0) / len(valid)
    return out


def high_stress():
    try:
        d = get_index_daily_data("VIX", 70)
        v = np.asarray(d.sort_values("date")["close"], float)
        return len(v) >= 25 and v[-1] > np.median(v[-25:-1])
    except Exception:
        return False


@register_hook
def strategy():
    global _calls
    if _calls % 10:
        _calls += 1
        return
    _calls += 1
    try:
        selected = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not selected or abs(sum(float(f["weight"]) for f in selected) - 1.0) > 1e-5:
        return

    prices = {}
    for asset in ASSETS:
        d = get_stock_daily_data(symbol=asset, days=280)
        if d is None or len(d) < 150:
            continue
        close = np.asarray(d.sort_values("date").iloc[:-1]["close"], float)
        if len(close) >= 130 and np.all(np.isfinite(close)) and np.all(close > 0):
            prices[asset] = close[-220:]
    if len(prices) < 12:
        return
    n = min(len(v) for v in prices.values())
    prices = {a: v[-n:] for a, v in prices.items()}
    rets = {a: np.diff(v) / v[:-1] for a, v in prices.items()}
    breadth = float(np.mean([np.mean(r[-20:] > 0) for r in rets.values()]))
    medvol = max(float(np.median([np.std(r[-20:], ddof=1) for r in rets.values()])), 0.008)
    raw = {a: {} for a in prices}
    for asset, close in prices.items():
        r = rets[asset]
        v20 = max(float(np.std(r[-20:], ddof=1)), 0.008)
        v40 = max(float(np.std(r[-40:], ddof=1)), 0.008)
        v60 = max(float(np.std(r[-60:], ddof=1)), 0.008)
        ret20 = close[-1] / close[-21] - 1
        ret60 = close[-1] / close[-61] - 1
        path = max(float(np.sum(np.abs(r[-60:]))), 1e-8)
        downside = max(float(np.std(np.minimum(r[-60:], 0), ddof=1)), 0.004)
        peak = np.maximum.accumulate(close[-61:])
        drawdown = abs(float(np.min(close[-61:] / peak - 1)))
        # These definitions are deliberately simple, causal proxies for the
        # persisted factor IDs; all inputs end at the last completed session.
        raw[asset] = {
            "miner_1_20301031_riskadjusted_momentum_60d": ret60 / v60,
            "miner_2_20301114_compressed_trend_reversal_60d": (-ret60 / v60) * (1 + min(v40 / v20, 2)),
            "miner_2_20301212_efficiency_reversal_60d": -ret60 / path / v20,
            "miner_3_20301128_range_stressed_reversal_60d": (-ret20 / v20) * (1 + min(drawdown, 0.5)),
            "miner_3_20301114_breadth_gated_contrarian_60d": (-ret20 / v20) * (1 + 2 * abs(breadth - 0.5)),
            "miner_1_20310821_choppy_residual_reversal_60d": 0.0,
            "miner_2_20300822_defensive_trend_quality_60d": (ret60 / v40) * (abs(np.sum(r[-40:])) / max(np.sum(np.abs(r[-40:])), 1e-8)),
            "miner_1_20300627_downside_stability_reversal_60d": -ret60 / downside * (1 - min(drawdown, 0.8)),
            "miner_3_20300822_volatility_dispersion_60d": -(v20 / medvol - 1),
        }
    mean60 = float(np.mean([v[-1] / v[-61] - 1 for v in prices.values()]))
    for asset, close in prices.items():
        r = rets[asset]
        residual = (close[-1] / close[-61] - 1) - mean60
        chop = min(float(np.sum(np.abs(r[-60:])) / max(abs(np.sum(r[-60:])), 0.01)), 4)
        raw[asset]["miner_1_20310821_choppy_residual_reversal_60d"] = -residual * (0.75 + 0.0625 * chop)

    score = {a: 0.0 for a in ASSETS}
    factor_ids = []
    for factor in selected:
        factor_id = str(factor["factor_id"])
        direction = int(factor.get("direction", 1))
        if factor_id not in raw[next(iter(raw))]:
            return
        factor_ids.append(factor_id)
        ranked = ranks({a: raw[a][factor_id] for a in raw})
        for asset in ASSETS:
            score[asset] += float(factor["weight"]) * direction * ranked[asset]
    if high_stress() or breadth < 0.45:
        for asset in ("XAU", "US10Y", "CN10Y"):
            score[asset] += 0.12
        for asset in ("BTC", "ETH", "WTI"):
            score[asset] -= 0.06

    values = np.array([score[a] for a in ASSETS])
    z = (values - values.mean()) / max(float(values.std()), 1e-9)
    weights = np.maximum(np.exp(0.10 * np.clip(z, -1.5, 1.5)), 0.025)
    weights /= weights.sum()
    target = {a: float(weights[i]) for i, a in enumerate(ASSETS)}
    forecast = {a: float(0.006 * z[i]) for i, a in enumerate(ASSETS)}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)

