        ids.append(fid)
        ranked = cross_rank({a: raw[a][fid] for a in raw})
        for a in ASSETS:
            score[a] += float(f["weight"]) * int(f.get("direction", 1)) * ranked[a]

    # High-risk recovery: use defensive tradables, never a cash sleeve.
    if stressed() or breadth < .45:
        for a in ("XAU", "US10Y", "CN10Y"):
            score[a] += .12
        for a in ("BTC", "ETH", "WTI"):
            score[a] -= .06

    z = (np.array([score[a] for a in ASSETS]) - np.mean(list(score.values()))) / max(float(np.std(list(score.values()))), 1e-9)
    w = np.maximum(np.exp(.10 * np.clip(z, -1.5, 1.5)), .025)
    w /= w.sum()
    target = {a: float(w[i]) for i, a in enumerate(ASSETS)}
    forecast = {a: float(.006 * z[i]) for i, a in enumerate(ASSETS)}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)

