    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
_calls = 0


def ranks(x):
    out = {a: 0.5 for a in ASSETS}
    good = sorted((a, float(v)) for a, v in x.items() if np.isfinite(v))
    if not good:
        return out
    for i, (a, _) in enumerate(good):
        out[a] = (i + 1.0) / len(good)
    return out


def stressed():
    try:
        d = get_index_daily_data("VIX", 70)
        v = np.asarray(d.sort_values("date")["close"], float)
        return len(v) >= 25 and v[-1] > np.median(v[-25:-1])
    except Exception:
        return False


@register_hook
def strategy():
    global _calls
    if _calls % 10:
        _calls += 1
        return
    _calls += 1
    try:
        factors = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not factors or abs(sum(float(f["weight"]) for f in factors) - 1.0) > 1e-5:
        return
    ids = [str(f["factor_id"]) for f in factors]

    prices = {}
    for a in ASSETS:
        d = get_stock_daily_data(symbol=a, days=280)
        if d is None or len(d) < 150:
            continue
        c = np.asarray(d.sort_values("date").iloc[:-1]["close"], float)
        if len(c) >= 130 and np.all(np.isfinite(c)) and np.all(c > 0):
            prices[a] = c[-220:]
    if len(prices) < 12:
        return
    n = min(len(c) for c in prices.values())
    prices = {a: c[-n:] for a, c in prices.items()}
    rets = {a: np.diff(c) / c[:-1] for a, c in prices.items()}
    medvol = max(float(np.median([np.std(r[-20:], ddof=1) for r in rets.values()])), .008)
    breadth = float(np.mean([np.mean(r[-20:] > 0) for r in rets.values()]))
    raw = {a: {} for a in prices}
    for a, c in prices.items():
        r = rets[a]
        v20 = max(float(np.std(r[-20:], ddof=1)), .008)
        v40 = max(float(np.std(r[-40:], ddof=1)), .008)
        v60 = max(float(np.std(r[-60:], ddof=1)), .008)
        ret20, ret60 = c[-1] / c[-21] - 1, c[-1] / c[-61] - 1
        path = max(float(np.sum(np.abs(r[-60:]))), 1e-8)
        downside = max(float(np.std(np.minimum(r[-60:], 0), ddof=1)), .004)
        peak = np.maximum.accumulate(c[-61:])
        dd = abs(float(np.min(c[-61:] / peak - 1)))
        raw[a] = {
            "miner_1_20301031_riskadjusted_momentum_60d": ret60 / v60,
            "miner_2_20300822_defensive_trend_quality_60d": ret60 / v40 * abs(np.sum(r[-40:])) / max(np.sum(np.abs(r[-40:])), 1e-8),
            "miner_3_20301128_range_stressed_reversal_60d": -ret20 / v20 * (1 + min(dd, .5)),
            "miner_2_20301212_efficiency_reversal_60d": -ret60 / path / v20,
            "miner_1_20300627_downside_stability_reversal_60d": -ret20 / downside,
            "miner_3_20301114_breadth_gated_contrarian_60d": -ret20 / v20 * (1 + 2 * abs(breadth - .5)),
            "miner_1_20310821_choppy_residual_reversal_60d": -ret20 / v20,
            "miner_2_20311113_volatility_compression_reversal_20d": -(ret20 / v20) * (1 - min(v20 / v60, 1)),
            "miner_3_20300822_volatility_dispersion_60d": -(v20 / medvol - 1),
        }
    if any(fid not in raw[next(iter(raw))] for fid in ids):
        return

    score = {a: 0.0 for a in ASSETS}
    for f in factors:
        rr = ranks({a: raw[a][str(f["factor_id"])] for a in raw})
        for a in ASSETS:
            score[a] += float(f["weight"]) * int(f.get("direction", 1)) * rr[a]
    if stressed() or breadth < .45:
        for a in ("XAU", "US10Y", "CN10Y"):
            score[a] += .12
        for a in ("BTC", "ETH", "WTI"):
            score[a] -= .06
    vals = np.array([score[a] for a in ASSETS])
    z = (vals - vals.mean()) / max(float(vals.std()), 1e-9)
    w = np.maximum(np.exp(.10 * np.clip(z, -1.5, 1.5)), .025)
    w /= w.sum()
    target = {a: float(w[i]) for i, a in enumerate(ASSETS)}
    forecast = {a: float(.006 * z[i]) for i, a in enumerate(ASSETS)}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)
"}

