import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
_calls = 0


def rank_cs(x):
    good = sorted((a, float(v)) for a, v in x.items() if np.isfinite(v))
    out = {a: 0.5 for a in ASSETS}
    if good:
        for i, (a, _) in enumerate(good):
            out[a] = (i + 1.0) / len(good)
    return out


def stressed():
    try:
        d = get_index_daily_data("VIX", 70)
        v = np.asarray(d.sort_values("date")["close"], float)
        return len(v) >= 30 and v[-1] > np.median(v[-30:-1])
    except Exception:
        return False


@register_hook
def strategy():
    global _calls
    if _calls % 10:
        _calls += 1
        return
    _calls += 1
    try:
        factors = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not factors or abs(sum(float(f["weight"]) for f in factors) - 1.0) > 1e-6:
        return
    ids = [str(f["factor_id"]) for f in factors]
    px = {}
    for a in ASSETS:
        d = get_stock_daily_data(symbol=a, days=300)
        if d is None or len(d) < 140:
            continue
        c = np.asarray(d.sort_values("date").iloc[:-1]["close"], float)
        if len(c) >= 125 and np.all(np.isfinite(c)) and np.all(c > 0):
            px[a] = c
    if len(px) < 12:
        return
    n = min(map(len, px.values()))
    px = {a: c[-n:] for a, c in px.items()}
    raw, v20s = {a: {} for a in px}, []
    for a, c in px.items():
        r = np.diff(c) / c[:-1]
        v20, v60 = max(np.std(r[-20:], ddof=1), .004), max(np.std(r[-60:], ddof=1), .004)
        v20s.append(v20)
        ret60, ret20 = c[-1] / c[-61] - 1, c[-1] / c[-21] - 1
        path = max(np.sum(np.abs(r[-60:])), 1e-8)
        peak = np.maximum.accumulate(c[-61:])
        drawdown = min(abs(np.min(c[-61:] / peak - 1)), .5)
        raw[a]["miner_1_20301031_riskadjusted_momentum_60d"] = -ret60 / v60
        raw[a]["miner_2_20301114_compressed_trend_reversal_60d"] = -ret60 / v60 * np.clip(v60 / v20, .5, 2.)
        raw[a]["miner_2_20301212_efficiency_reversal_60d"] = -ret60 / path / v20
        raw[a]["miner_3_20301128_range_stressed_reversal_60d"] = -ret20 / v20 * (1 + drawdown)
        raw[a]["miner_3_20300822_volatility_dispersion_60d"] = -(v20 / max(np.median(v20s), .004) - 1)
    score = {a: 0.0 for a in ASSETS}
    for f in factors:
        fid = str(f["factor_id"])
        if fid not in raw[next(iter(raw))]:
            return
        rr = rank_cs({a: raw[a][fid] for a in raw})
        for a in ASSETS:
            score[a] += float(f["weight"]) * int(f.get("direction", 1)) * rr[a]
    breadth = np.mean([np.mean(np.diff(c[-21:]) / c[-21:-1] > 0) for c in px.values()])
    if stressed() or breadth < .45:
        for a in ("XAU", "US10Y", "CN10Y"):
            score[a] += .12
        for a in ("BTC", "ETH", "WTI"):
            score[a] -= .06
    vals = np.array([score[a] for a in ASSETS])
    z = (vals - vals.mean()) / max(vals.std(), 1e-9)
    w = np.maximum(np.exp(.10 * np.clip(z, -1.5, 1.5)), .025)
    w /= w.sum()
    target = {a: float(w[i]) for i, a in enumerate(ASSETS)}
    forecast = {a: float(.006 * z[i]) for i, a in enumerate(ASSETS)}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)

