import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factor_ensemble.json"
_calls = 0

def pct_rank(vals):
    out = {a: .5 for a in ASSETS}
    good = sorted((a, float(v)) for a, v in vals.items() if np.isfinite(v))
    for i, (a, _) in enumerate(good): out[a] = (i + 1.) / len(good)
    return out

def high_stress():
    try:
        d = get_index_daily_data("VIX", 70)
        v = np.asarray(d.sort_values("date")["close"], float)
        return len(v) >= 31 and v[-1] > np.median(v[-31:-1])
    except Exception: return False

@register_hook
def strategy():
    global _calls
    if _calls % 10: _calls += 1; return
    _calls += 1
    try: fs = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception: return
    if not fs or abs(sum(float(f["weight"]) for f in fs)-1) > 1e-6: return
    ids = [str(f["factor_id"]) for f in fs]
    px = {}
    for a in ASSETS:
        d = get_stock_daily_data(symbol=a, days=450)
        if d is not None and len(d) >= 140:
            c = np.asarray(d.sort_values("date").iloc[:-1]["close"], float)
            if len(c) >= 125 and np.all(np.isfinite(c)) and np.all(c > 0): px[a] = c
    if len(px) < 12: return
    n = min(len(x) for x in px.values()); px = {a:x[-n:] for a,x in px.items()}
    rets = {a:np.diff(c)/c[:-1] for a,c in px.items()}
    v20 = {a:max(float(np.std(r[-20:], ddof=1)),.004) for a,r in rets.items()}
    v60 = {a:max(float(np.std(r[-60:], ddof=1)),.004) for a,r in rets.items()}
    medv = max(float(np.median(list(v20.values()))), .004)
    # Signals reproduce the persisted factor definitions using only completed data.
    raw = {a:{} for a in px}
    ret60s = {a:px[a][-1]/px[a][-61]-1 for a in px}
    crossmed = float(np.median(list(ret60s.values())))
    disp = float(np.median([abs(x-crossmed) for x in ret60s.values()]))
    for a,c in px.items():
        r=rets[a]; ret60=ret60s[a]; ret20=c[-1]/c[-21]-1
        path=max(float(np.sum(np.abs(r[-60:]))),1e-8)
        # dispersion recovery: 10d recovery normalized by 40d vol, cross-sectional dispersion
        rec=(c[-1]/c[-11]-1)/(max(float(np.std(r[-40:],ddof=1)),.004)*np.sqrt(10))
        raw[a]["miner_1_20320401_dispersion_recovery_reversal_60d"]=(crossmed-ret60)*(1+.25*np.clip(rec,-1,1))*np.clip(disp/max(disp,.0001),.5,2)
        raw[a]["miner_1_20301031_riskadjusted_momentum_60d"]=-ret60/v60[a]
        down=np.std(np.minimum(r[-60:],0),ddof=1) if len(r)>=20 else v60[a]
        turn=ret20-(ret60/12.)
        raw[a]["miner_3_20320401_dual_horizon_reversal_60d"]=(-ret20/(max(down,0.004)+v60[a]))*(1+np.clip(turn,-.25,.25))
        raw[a]["miner_2_20301114_compressed_trend_reversal_60d"]=(-ret60/v60[a])*np.clip(v60[a]/v20[a],.5,2)
        raw[a]["miner_2_20301212_efficiency_reversal_60d"]=-ret60/path/v20[a]
        raw[a]["miner_3_20300822_volatility_dispersion_60d"]=-(v20[a]/medv-1)
    score={a:0. for a in ASSETS}
    for f in fs:
        fid=str(f["factor_id"])
        if fid not in raw[next(iter(raw))]: return
        rr=pct_rank({a:raw[a][fid] for a in raw})
        for a in ASSETS: score[a]+=float(f["weight"])*int(f.get("direction",1))*rr[a]
    breadth=float(np.mean([np.mean(np.diff(c[-21:])/c[-21:-1]>0) for c in px.values()]))
    if high_stress() or breadth < .45:
        for a in ("XAU","US10Y","CN10Y"): score[a]+=.12
        for a in ("BTC","ETH","WTI"): score[a]-=.06
    z=(np.array([score[a] for a in ASSETS])-np.mean(list(score.values())))/max(float(np.std(list(score.values()))),1e-9)
    w=np.maximum(np.exp(.10*np.clip(z,-1.5,1.5)),.025); w/=w.sum()
    target={a:float(w[i]) for i,a in enumerate(ASSETS)}
    forecast={a:float(.006*z[i]) for i,a in enumerate(ASSETS)}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)

