from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
_calls = 0

def ranks(x):
    out = {a: .5 for a in ASSETS}
    q = sorted((a, v) for a, v in x.items() if np.isfinite(v))
    for i, (a, _) in enumerate(q): out[a] = (i + 1.) / max(len(q), 1)
    return out

def stressed():
    try:
        d = get_index_daily_data("VIX", 70)
        v = np.asarray(d.sort_values("date")["close"], float)
        return len(v) >= 32 and v[-1] > np.median(v[-31:-1])
    except Exception:
        return False

@register_hook
def strategy():
    global _calls
    if _calls % 10 != 0:
        _calls += 1
        return
    _calls += 1
    try:
        fs = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not fs or abs(sum(float(f["weight"]) for f in fs) - 1.) > 1e-5:
        return
    ids = [str(f["factor_id"]) for f in fs]
    frames = {}
    for a in ASSETS:
        d = get_stock_daily_data(symbol=a, days=450)
        if d is not None and len(d) >= 150:
            frames[a] = d.sort_values("date").iloc[:-1].copy()
    if len(frames) < 12:
        return
    n = min(len(d) for d in frames.values())
    frames = {a: d.iloc[-n:] for a, d in frames.items()}
    close = {a: np.asarray(d.close, float) for a, d in frames.items()}
    ret = {a: np.diff(close[a]) / close[a][:-1] for a in close}
    v20 = {a: max(float(np.std(ret[a][-20:], ddof=1)), .004) for a in close}
    v30 = {a: max(float(np.std(ret[a][-30:], ddof=1)), .004) for a in close}
    v60 = {a: max(float(np.std(ret[a][-60:], ddof=1)), .004) for a in close}
    r60 = {a: close[a][-1] / close[a][-61] - 1. for a in close}
    r20 = {a: close[a][-1] / close[a][-21] - 1. for a in close}
    med60 = float(np.median(list(r60.values())))
    dispersion = max(float(np.median([abs(v-med60) for v in r60.values()])), .0001)
    medv = max(float(np.median(list(v20.values()))), .004)
    raw = {a: {} for a in close}
    for a, c in close.items():
        rr = ret[a]
        path = max(float(np.sum(np.abs(rr[-60:]))), 1e-8)
