        raw[a]["miner_2_20301114_compressed_trend_reversal_60d"] = (-r60[a] / v60[a]) * np.clip(v60[a] / v20[a], .5, 2.)
        raw[a]["miner_2_20301212_efficiency_reversal_60d"] = -r60[a] / path / v20[a]
        intr = np.asarray(frames[a].high, float)[-20:] - np.asarray(frames[a].low, float)[-20:]
        intr = np.maximum(intr / c[-20:], 0.)
        range_mean = float(np.mean(intr))
        # Cross-sectional current range stress is a robust proxy for the factor's 90d normalizer.
        raw[a]["miner_3_20301128_range_stressed_reversal_60d"] = (-r20[a] / v30[a]) * np.clip(range_mean / max(np.median([np.mean(np.maximum((np.asarray(frames[b].high,float)[-20:]-np.asarray(frames[b].low,float)[-20:]) / close[b][-20:],0.)) for b in close]), 1e-5), .5, 2.)
