        raw[a]["miner_1_20320401_dispersion_recovery_reversal_60d"] = (med60-r60[a]) * (1+.25*np.clip(recovery,-1,1)) * dispersion / max(dispersion, .0001)
        raw[a]["miner_3_20300822_volatility_dispersion_60d"] = -(v20[a] / medv - 1.)
    score = {a: 0. for a in ASSETS}
