import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
_calls = 0


def xrank(values):
    out = {a: 0.5 for a in ASSETS}
    valid = sorted((a, float(v)) for a, v in values.items() if np.isfinite(v))
    for i, (a, _) in enumerate(valid):
        out[a] = (i + 1.0) / len(valid)
    return out


def stressed():
    try:
        d = get_index_daily_data("VIX", 70)
        v = np.asarray(d.sort_values("date")["close"], dtype=float)
        return len(v) >= 32 and v[-1] > np.median(v[-31:-1])
    except Exception:
        return False


@register_hook
def strategy():
    global _calls
    if _calls % 10:
        _calls += 1
        return
    _calls += 1
    try:
        fs = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not fs or abs(sum(float(f["weight"]) for f in fs) - 1.0) > 1e-6:
        return
    ids = [str(f["factor_id"]) for f in fs]

    frames = {}
    for a in ASSETS:
        d = get_stock_daily_data(symbol=a, days=450)
        if d is not None and len(d) >= 150:
            # The last row is not used: decisions see only completed prior sessions.
            frames[a] = d.sort_values("date").iloc[:-1].copy()
    if len(frames) < len(ASSETS):
        return
    n = min(len(d) for d in frames.values())
    close = {a: np.asarray(frames[a].iloc[-n:]["close"], dtype=float) for a in ASSETS}
    rets = {a: np.diff(close[a]) / np.maximum(close[a][:-1], 1e-12) for a in ASSETS}
    v20 = {a: max(float(np.std(rets[a][-20:], ddof=1)), .004) for a in ASSETS}
    v60 = {a: max(float(np.std(rets[a][-60:], ddof=1)), .004) for a in ASSETS}
    r20 = {a: close[a][-1] / close[a][-21] - 1.0 for a in ASSETS}
    r60 = {a: close[a][-1] / close[a][-61] - 1.0 for a in ASSETS}
    med_r = float(np.median(list(r60.values())))
    med_v = max(float(np.median(list(v20.values()))), .004)

    raw = {a: {} for a in ASSETS}
    for a in ASSETS:
        rr = rets[a]
        path = max(float(np.sum(np.abs(rr[-60:]))), 1e-8)
        lo, hi = float(np.min(close[a][-60:])), float(np.max(close[a][-60:]))
        pos = (close[a][-1] - lo) / max(hi - lo, 1e-12)
        raw[a]["miner_1_20301031_riskadjusted_momentum_60d"] = r60[a] / v60[a]
        raw[a]["miner_2_20301212_efficiency_reversal_60d"] = -r60[a] / path
        raw[a]["miner_1_20320401_dispersion_recovery_reversal_60d"] = med_r - r60[a]
        raw[a]["miner_3_20320610_volatility_normalized_reversal_60d"] = -.65*r60[a]/v60[a] -.35*r20[a]/v20[a]
        raw[a]["miner_3_20301128_range_stressed_reversal_60d"] = (0.5 - pos) * (v60[a] / med_v)
        raw[a]["miner_3_20320527_range_position_reversal_60d"] = 0.5 - pos
        raw[a]["miner_3_20300822_volatility_dispersion_60d"] = -(v20[a] / med_v - 1.0)

    score = {a: 0.0 for a in ASSETS}
    for f in fs:
        fid = str(f["factor_id"])
        if fid not in raw[ASSETS[0]]:
            return
        ranks = xrank({a: raw[a][fid] for a in ASSETS})
        for a in ASSETS:
            score[a] += float(f["weight"]) * int(f.get("direction", 1)) * ranks[a]

    # High VIX/breadth stress is expressed by defensive tradable assets, never cash.
    breadth = float(np.mean([np.mean(rets[a][-20:] > 0) for a in ASSETS]))
    if stressed() or breadth < .45:
        for a in ("XAU", "US10Y", "CN10Y"):
            score[a] += .12
        for a in ("BTC", "ETH", "WTI"):
            score[a] -= .06

    vals = np.array([score[a] for a in ASSETS], dtype=float)
    z = (vals - vals.mean()) / max(float(vals.std()), 1e-9)
    weights = np.maximum(np.exp(.10 * np.clip(z, -1.5, 1.5)), .025)
    weights /= weights.sum()
    target = {a: float(weights[i]) for i, a in enumerate(ASSETS)}
    forecast = {a: float(.006 * z[i]) for i, a in enumerate(ASSETS)}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)

