import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
_calls = 0

def rank(x):
    good = sorted((a, float(v)) for a, v in x.items() if np.isfinite(v))
    out = {a: .5 for a in ASSETS}
    if good:
        for i, (a, _) in enumerate(good): out[a] = (i + 1) / len(good)
    return out

def vix_stress():
    try:
        d = get_index_daily_data("VIX", 70)
        v = np.asarray(d.sort_values("date")["close"], float)
        return len(v) >= 32 and v[-1] > np.median(v[-31:-1])
    except Exception:
        return False

@register_hook
def strategy():
    global _calls
    if _calls % 10:
        _calls += 1
        return
    _calls += 1
    try: fs = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception: return
    if not fs or abs(sum(float(f["weight"]) for f in fs) - 1) > 1e-6: return
    ids = [str(f["factor_id"]) for f in fs]
    data = {}
    for a in ASSETS:
        d = get_stock_daily_data(symbol=a, days=450)
        if d is not None and len(d) >= 150: data[a] = d.sort_values("date").iloc[:-1]
    if len(data) != 15: return
    n = min(len(d) for d in data.values())
    c = {a: np.asarray(data[a].iloc[-n:]["close"], float) for a in ASSETS}
    r = {a: np.diff(c[a]) / np.maximum(c[a][:-1], 1e-12) for a in ASSETS}
    vol20 = {a: max(float(np.std(r[a][-20:], ddof=1)), .004) for a in ASSETS}
    vol40 = {a: max(float(np.std(r[a][-40:], ddof=1)), .004) for a in ASSETS}
    vol60 = {a: max(float(np.std(r[a][-60:], ddof=1)), .004) for a in ASSETS}
    r10 = {a: c[a][-1] / c[a][-11] - 1 for a in ASSETS}
    r60 = {a: c[a][-1] / c[a][-61] - 1 for a in ASSETS}
    med60 = float(np.median(list(r60.values())))
    medv = max(float(np.median(list(vol20.values()))), .004)
    breadth = float(np.mean([np.mean(r[a][-20:] > 0) for a in ASSETS]))
    raw = {a: {} for a in ASSETS}
    for a in ASSETS:
        peak = max(c[a][-120:])
        dd = max(0., 1 - c[a][-1] / max(peak, 1e-12))
        rebound = max(float(np.sum(r[a][-10:])), 0.)
        path = max(float(np.sum(np.abs(r[a][-60:]))), 1e-8)
        raw[a]["miner_1_20301031_riskadjusted_momentum_60d"] = -r60[a] / vol60[a]
        raw[a]["miner_1_20320624_peak_drawdown_recovery_60d"] = dd / vol60[a] * (.5 + rebound)
        raw[a]["miner_1_20320401_dispersion_recovery_reversal_60d"] = (med60-r60[a]) * (1 + .25*np.clip(r10[a]/(vol40[a]*np.sqrt(10)), -1, 1))
        raw[a]["miner_3_20300711_breadth_confirmed_trend_reversal_60d"] = (-r60[a]/vol40[a]) * (max((breadth-.5)*2, 0) + .25)
        raw[a]["miner_3_20300822_volatility_dispersion_60d"] = -(vol20[a]/medv - 1)
        raw[a]["miner_1_20310529_volatility_term_structure_20d"] = -(max(float(np.std(r[a][-10:], ddof=1)), .004)/vol60[a] - 1)
    score = {a: 0. for a in ASSETS}
    for f in fs:
        fid = str(f["factor_id"])
        if fid not in raw[ASSETS[0]]: return
        rr = rank({a: raw[a][fid] for a in ASSETS})
        for a in ASSETS: score[a] += float(f["weight"]) * int(f.get("direction", 1)) * rr[a]
    if vix_stress() or breadth < .45:
        for a in ("XAU", "US10Y", "CN10Y"): score[a] += .12
        for a in ("BTC", "ETH", "WTI"): score[a] -= .06
    z = (np.array([score[a] for a in ASSETS]) - np.mean(list(score.values()))) / max(np.std(list(score.values())), 1e-9)
    w = np.maximum(np.exp(.10*np.clip(z, -1.5, 1.5)), .025); w /= w.sum()
    target = {a: float(w[i]) for i, a in enumerate(ASSETS)}
    forecast = {a: float(.006*z[i]) for i, a in enumerate(ASSETS)}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)

