_calls = 0


def xrank(values):
    out = {a: 0.5 for a in ASSETS}
    valid = sorted((a, float(v)) for a, v in values.items() if np.isfinite(v))
    for i, (a, _) in enumerate(valid):
        out[a] = (i + 1.0) / len(valid)
    return out


def stressed():
    try:
        d = get_index_daily_data("VIX", 70)
        v = np.asarray(d.sort_values("date")["close"], dtype=float)
        return len(v) >= 32 and v[-1] > np.median(v[-31:-1])
    except Exception:
        return False


@register_hook
def strategy():
    global _calls
    if _calls % 10:
        _calls += 1
        return
    _calls += 1
    try:
