            frames[a] = d.sort_values("date").iloc[:-1].copy()
    if len(frames) < len(ASSETS):
        return
    n = min(len(d) for d in frames.values())
    close = {a: np.asarray(frames[a].iloc[-n:]["close"], dtype=float) for a in ASSETS}
    rets = {a: np.diff(close[a]) / np.maximum(close[a][:-1], 1e-12) for a in ASSETS}
    v20 = {a: max(float(np.std(rets[a][-20:], ddof=1)), .004) for a in ASSETS}
    v60 = {a: max(float(np.std(rets[a][-60:], ddof=1)), .004) for a in ASSETS}
    r20 = {a: close[a][-1] / close[a][-21] - 1.0 for a in ASSETS}
    r60 = {a: close[a][-1] / close[a][-61] - 1.0 for a in ASSETS}
    med_r = float(np.median(list(r60.values())))
    med_v = max(float(np.median(list(v20.values()))), .004)

    raw = {a: {} for a in ASSETS}
    for a in ASSETS:
        rr = rets[a]
        path = max(float(np.sum(np.abs(rr[-60:]))), 1e-8)
