        raw[a]["miner_3_20301128_range_stressed_reversal_60d"] = (0.5 - pos) * (v60[a] / med_v)
        raw[a]["miner_3_20320527_range_position_reversal_60d"] = 0.5 - pos
        raw[a]["miner_3_20300822_volatility_dispersion_60d"] = -(v20[a] / med_v - 1.0)

    score = {a: 0.0 for a in ASSETS}
    for f in fs:
        fid = str(f["factor_id"])
        if fid not in raw[ASSETS[0]]:
            return
        ranks = xrank({a: raw[a][fid] for a in ASSETS})
        for a in ASSETS:
            score[a] += float(f["weight"]) * int(f.get("direction", 1)) * ranks[a]

    # High VIX/breadth stress is expressed by defensive tradable assets, never cash.
    breadth = float(np.mean([np.mean(rets[a][-20:] > 0) for a in ASSETS]))
    if stressed() or breadth < .45:
        for a in ("XAU", "US10Y", "CN10Y"):
            score[a] += .12
        for a in ("BTC", "ETH", "WTI"):
            score[a] -= .06

    vals = np.array([score[a] for a in ASSETS], dtype=float)
    z = (vals - vals.mean()) / max(float(vals.std()), 1e-9)
    weights = np.maximum(np.exp(.10 * np.clip(z, -1.5, 1.5)), .025)
    weights /= weights.sum()
    target = {a: float(weights[i]) for i, a in enumerate(ASSETS)}
    forecast = {a: float(.006 * z[i]) for i, a in enumerate(ASSETS)}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)
