import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
_calls = 0


def cross_rank(values):
    finite = sorted((a, float(v)) for a, v in values.items() if np.isfinite(v))
    out = {a: 0.5 for a in ASSETS}
    if finite:
        for i, (a, _) in enumerate(finite):
            out[a] = (i + 1.0) / len(finite)
    return out


def stressed():
    try:
        d = get_index_daily_data("VIX", 70)
        x = np.asarray(d.sort_values("date")["close"], dtype=float)
        return len(x) >= 32 and x[-1] > np.median(x[-31:-1])
    except Exception:
        return False


@register_hook
def strategy():
    global _calls
    if _calls % 10 != 0:
        _calls += 1
        return
    _calls += 1
    try:
        factors = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not factors or abs(sum(float(f["weight"]) for f in factors) - 1.0) > 1e-6:
        return
    factor_ids = [str(f["factor_id"]) for f in factors]

    prices = {}
    for asset in ASSETS:
        d = get_stock_daily_data(asset, 450)
        if d is None or len(d) < 150:
            return
        # The final row can be today's incomplete observation at a decision.
        prices[asset] = np.asarray(d.sort_values("date").iloc[:-1]["close"], dtype=float)
    if any(len(prices[a]) < 130 for a in ASSETS):
        return
    n = min(len(prices[a]) for a in ASSETS)
    close = {a: prices[a][-n:] for a in ASSETS}
    ret = {a: np.diff(close[a]) / np.maximum(close[a][:-1], 1e-12) for a in ASSETS}
    vol20 = {a: max(float(np.std(ret[a][-20:], ddof=1)), .004) for a in ASSETS}
    vol40 = {a: max(float(np.std(ret[a][-40:], ddof=1)), .004) for a in ASSETS}
    vol60 = {a: max(float(np.std(ret[a][-60:], ddof=1)), .004) for a in ASSETS}
    r10 = {a: close[a][-1] / close[a][-11] - 1 for a in ASSETS}
    r60 = {a: close[a][-1] / close[a][-61] - 1 for a in ASSETS}
    median_r60 = float(np.median(list(r60.values())))
    median_v20 = max(float(np.median(list(vol20.values()))), .004)
    breadth = float(np.mean([np.mean(ret[a][-20:] > 0) for a in ASSETS]))

    raw = {a: {} for a in ASSETS}
    for a in ASSETS:
        peak = max(close[a][-120:])
        drawdown = max(0.0, 1.0 - close[a][-1] / max(peak, 1e-12))
        rebound = max(float(np.sum(ret[a][-10:])), 0.0)
        raw[a]["miner_1_20301031_riskadjusted_momentum_60d"] = r60[a] / vol60[a]
        raw[a]["miner_1_20320624_peak_drawdown_recovery_60d"] = drawdown / vol60[a] * (0.5 + rebound)
        raw[a]["miner_1_20320401_dispersion_recovery_reversal_60d"] = (median_r60 - r60[a]) * (1.0 + .25 * np.clip(r10[a] / (vol40[a] * np.sqrt(10)), -1, 1))
        raw[a]["miner_3_20300711_breadth_confirmed_trend_reversal_60d"] = (-r60[a] / vol40[a]) * (max((breadth - .5) * 2, 0) + .25)
        raw[a]["miner_3_20300822_volatility_dispersion_60d"] = -(vol20[a] / median_v20 - 1.0)
        raw[a]["miner_1_20310529_volatility_term_structure_20d"] = -(max(float(np.std(ret[a][-10:], ddof=1)), .004) / vol60[a] - 1.0)

    score = {a: 0.0 for a in ASSETS}
    for f in factors:
        fid = str(f["factor_id"])
        if fid not in raw[ASSETS[0]]:
            return
        ranks = cross_rank({a: raw[a][fid] for a in ASSETS})
        direction = int(f.get("direction", 1))
        for a in ASSETS:
            score[a] += float(f["weight"]) * direction * ranks[a]

    # High risk is expressed by defensive tradable assets, never cash.
    if stressed() or breadth < .45:
        for a in ("XAU", "US10Y", "CN10Y"):
            score[a] += .12
        for a in ("BTC", "ETH", "WTI"):
            score[a] -= .06

    vals = np.asarray([score[a] for a in ASSETS], dtype=float)
    z = (vals - vals.mean()) / max(float(vals.std()), 1e-9)
    weights = np.maximum(np.exp(.10 * np.clip(z, -1.5, 1.5)), .025)
    weights /= weights.sum()
    target = {a: float(weights[i]) for i, a in enumerate(ASSETS)}
    forecast = {a: float(.006 * z[i]) for i, a in enumerate(ASSETS)}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)

