        raw[a]["miner_3_20300711_breadth_confirmed_trend_reversal_60d"] = (-r60[a] / v40[a]) * (0.25 + max(2.0 * (breadth - 0.5), 0.0))
        raw[a]["miner_3_20300822_volatility_dispersion_60d"] = -(v20[a] / median_v20 - 1.0)
    score = {a: 0.0 for a in ASSETS}
    for f in fs:
        fid = str(f["factor_id"])
