import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
_calls = 0


def ranks(x):
    good = {a: float(v) for a, v in x.items() if np.isfinite(v)}
    order = sorted(good, key=good.get)
    out = {a: 0.5 for a in ASSETS}
    for i, a in enumerate(order):
        out[a] = (i + 1.0) / max(1, len(order))
    return out


def stressed():
    try:
        d = get_index_daily_data("VIX", 70)
        v = np.asarray(d.sort_values("date")["close"], float)
        return len(v) >= 35 and v[-1] > np.median(v[-31:-1])
    except Exception:
        return False


@register_hook
def strategy():
    global _calls
    if _calls % 10:
        _calls += 1
        return
    _calls += 1
    try:
        fs = json.loads(ENSEMBLE.read_text())["selected_factors"][:10]
    except Exception:
        return
    if not fs or abs(sum(float(f["weight"]) for f in fs) - 1.0) > 1e-6:
        return
    factor_ids = [str(f["factor_id"]) for f in fs]
    close = {}
    for a in ASSETS:
        d = get_stock_daily_data(a, 450)
        if d is None or len(d) < 153:
            return
        # Exclude the current/incomplete bar: decisions use completed history only.
        x = np.asarray(d.sort_values("date").iloc[:-1]["close"], float)
        close[a] = x[-400:]
    n = min(len(x) for x in close.values())
    close = {a: x[-n:] for a, x in close.items()}
    ret = {a: np.diff(x) / np.maximum(x[:-1], 1e-12) for a, x in close.items()}
    v20 = {a: max(float(np.std(r[-20:], ddof=1)), .004) for a, r in ret.items()}
    v60 = {a: max(float(np.std(r[-60:], ddof=1)), .004) for a, r in ret.items()}
    r60 = {a: close[a][-1] / close[a][-61] - 1 for a in ASSETS}
    r120 = {a: close[a][-1] / close[a][-121] - 1 for a in ASSETS}
    med_r60 = float(np.median(list(r60.values())))
    med_v20 = max(float(np.median(list(v20.values()))), .004)
    breadth = float(np.mean([np.mean(ret[a][-20:] > 0) for a in ASSETS]))
    raw = {a: {} for a in ASSETS}
    for a in ASSETS:
        peak = max(close[a][-120:])
        dd = max(0., 1. - close[a][-1] / max(peak, 1e-12))
        rebound = max(float(np.sum(ret[a][-10:])), 0.)
        raw[a]["miner_1_20301031_riskadjusted_momentum_60d"] = -r120[a] / v60[a]
        raw[a]["miner_1_20320624_peak_drawdown_recovery_60d"] = dd * (0.5 + rebound) / v60[a]
        raw[a]["miner_1_20320401_dispersion_recovery_reversal_60d"] = (med_r60 - r60[a]) / v60[a]
        raw[a]["miner_3_20300711_breadth_confirmed_trend_reversal_60d"] = (-r60[a] / v60[a]) * (0.25 + max(2 * (breadth - .5), 0.))
        # (-60d return / 60d vol) times clipped long/short volatility ratio.
        ratio = np.clip(v60[a] / v20[a], .5, 2.)
        raw[a]["miner_2_20301114_compressed_trend_reversal_60d"] = (-r60[a] / v60[a]) * ratio
        # Cross-sectional volatility dispersion, expressed as a stable low-volatility tilt.
        raw[a]["miner_3_20300822_volatility_dispersion_60d"] = -(v20[a] / med_v20 - 1.)
    score = {a: 0. for a in ASSETS}
    for f in fs:
        fid = str(f["factor_id"])
        if fid not in raw[ASSETS[0]]:
            return
        rr = ranks({a: raw[a][fid] for a in ASSETS})
        for a in ASSETS:
            score[a] += float(f["weight"]) * int(f.get("direction", 1)) * rr[a]
    # Extended rebound but medium-high risk: retain full investment and modestly
    # reserve weight for tradable defensives, never cash.
    if stressed() or breadth < .45:
        for a in ("XAU", "US10Y", "CN10Y"):
            score[a] += .12
        for a in ("BTC", "ETH", "WTI"):
            score[a] -= .06
    z = (np.asarray([score[a] for a in ASSETS]) - np.mean(list(score.values()))) / max(np.std(list(score.values())), 1e-9)
    w = np.maximum(np.exp(.10 * np.clip(z, -1.5, 1.5)), .025)
    w /= w.sum()
    target = {a: float(w[i]) for i, a in enumerate(ASSETS)}
    forecast = {a: float(.006 * z[i]) for i, a in enumerate(ASSETS)}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)

