import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
_calls = 0


def xrank(values):
    finite = {a: float(v) for a, v in values.items() if np.isfinite(v)}
    result = {a: 0.5 for a in ASSETS}
    ordered = sorted(finite, key=finite.get)
    for i, a in enumerate(ordered):
        result[a] = (i + 1) / max(1, len(ordered))
    return result


def elevated_risk():
    try:
        d = get_index_daily_data("VIX", 70)
        x = np.asarray(d.sort_values("date")["close"], dtype=float)
        return len(x) >= 35 and (x[-1] > np.median(x[-31:-1]) * 1.15 or x[-1] > 18)
    except Exception:
        return False


@register_hook
def strategy():
    global _calls
    if _calls % 10 != 0:
        _calls += 1
        return
    _calls += 1
    try:
        factors = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return
    if not factors or abs(sum(float(f["weight"]) for f in factors) - 1.0) > 1e-6:
        return
    factor_ids = [str(f["factor_id"]) for f in factors]

    close = {}
    for asset in ASSETS:
        d = get_stock_daily_data(asset, 450)
        if d is None or len(d) < 160:
            return
        # The last row can be today's incomplete session at a decision.
        p = np.asarray(d.sort_values("date")["close"], dtype=float)
        close[asset] = p[:-1][-400:]
    n = min(len(v) for v in close.values())
    close = {a: v[-n:] for a, v in close.items()}
    returns = {a: np.diff(close[a]) / np.maximum(close[a][:-1], 1e-12) for a in ASSETS}
    v20 = {a: max(float(np.std(returns[a][-20:], ddof=1)), 0.004) for a in ASSETS}
    v60 = {a: max(float(np.std(returns[a][-60:], ddof=1)), 0.004) for a in ASSETS}
    median_v20 = max(float(np.median(list(v20.values()))), 0.004)

    raw = {a: {} for a in ASSETS}
    # Proxies are deliberately simple, lagged, and available for every asset.
    for a in ASSETS:
        p = close[a]
        r20, r60, r120 = p[-1] / p[-21] - 1, p[-1] / p[-61] - 1, p[-1] / p[-121] - 1
        peak = max(np.max(p[-61:]), 1e-12)
        recovery = (p[-1] / peak - 1) + max(r60, 0)
        range_pos = (p[-1] - np.min(p[-61:])) / max(np.ptp(p[-61:]), 1e-12)
        vol_ratio = np.clip(v60[a] / v20[a], 0.5, 2.0)
        raw[a]["miner_2_20301114_compressed_trend_reversal_60d"] = -r60 * vol_ratio / v60[a]
        raw[a]["miner_1_20320624_peak_drawdown_recovery_60d"] = recovery / v60[a]
        raw[a]["miner_1_20320401_dispersion_recovery_reversal_60d"] = -r60 / v60[a]
        raw[a]["miner_3_20301128_range_stressed_reversal_60d"] = -r20 * (1 + abs(range_pos - 0.5)) / v20[a]
        raw[a]["miner_1_20301031_riskadjusted_momentum_60d"] = r60 / v60[a]
        raw[a]["miner_3_20300822_volatility_dispersion_60d"] = -(v20[a] / median_v20 - 1)
        raw[a]["miner_1_20310529_volatility_term_structure_20d"] = -(v20[a] / v60[a] - 1)
        # Long-horizon trend quality; ensemble direction -1 intentionally inverts it.
        raw[a]["miner_2_20321028_long_trend_quality_60d"] = r120 / v60[a]

    score = {a: 0.0 for a in ASSETS}
    for f in factors:
        fid = str(f["factor_id"])
        if fid not in raw[ASSETS[0]]:
            return
        ranks = xrank({a: raw[a][fid] for a in ASSETS})
        for a in ASSETS:
            score[a] += float(f["weight"]) * int(f.get("direction", 1)) * ranks[a]

    breadth = float(np.mean([np.mean(returns[a][-20:] > 0) for a in ASSETS]))
    if elevated_risk() or breadth < 0.45:
        for a in ("XAU", "US10Y", "CN10Y"):
            score[a] += 0.12
        for a in ("BTC", "ETH", "WTI"):
            score[a] -= 0.06

    vals = np.array([score[a] for a in ASSETS], dtype=float)
    z = (vals - vals.mean()) / max(vals.std(), 1e-9)
    # Flat exponential tilt limits reversal-cluster concentration while remaining fully invested.
    weights = np.maximum(np.exp(0.10 * np.clip(z, -1.5, 1.5)), 0.025)
    weights /= weights.sum()
    target = {a: float(weights[i]) for i, a in enumerate(ASSETS)}
    forecast = {a: float(0.006 * z[i]) for i, a in enumerate(ASSETS)}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)

