    for i, a in enumerate(sorted(good, key=lambda a: x[a])):
        out[a] = (i + 1) / len(good)
    return out

def macro_series():
    out = []
    for s in ("VIX", "DXY", "USDCNY"):
        d = get_index_daily_data(s, 100)
