            return None
        out.append(np.asarray(d.sort_values("date")["close"], float))
    n = min(map(len, out))
    z = []
    for x in out:
        r = np.diff(x[-n:]) / np.maximum(x[-n:-1], 1e-12)
        z.append((r - np.mean(r[-60:])) / max(np.std(r[-60:], ddof=1), .004))
    return np.mean(z, axis=0)

@register_hook
def strategy():
    global _calls
    if _calls % 10:
        _calls += 1
