ENSEMBLES = [Path(__file__).parent / "factors" / "factor_ensemble.json", Path(__file__).parent / "factor_ensemble.json"]
_calls = 0

def rank(v):
    ok = [a for a in ASSETS if np.isfinite(v.get(a, np.nan))]
    out = {a: .5 for a in ASSETS}
    for i, a in enumerate(sorted(ok, key=lambda x: v[x])):
        out[a] = (i + 1.) / len(ok)
    return out

def ensemble():
    for p in ENSEMBLES:
        if p.exists():
            x = json.loads(p.read_text()).get("selected_factors", [])[:10]
            if x and abs(sum(float(f["weight"]) for f in x) - 1.) < 1e-6:
                return x
    return []

@register_hook
def strategy():
    global _calls
    if _calls % 10:
        _calls += 1
        return
    _calls += 1
    factors = ensemble()
    if not factors:
        return
    ids = [str(f["factor_id"]) for f in factors]
    close = {}
    for a in ASSETS:
        d = get_stock_daily_data(a, 450)
        if d is None or len(d) < 170:
            return
        x = np.asarray(d.sort_values("date")["close"], float)
        # Exclude the potentially incomplete current bar.
        close[a] = x[:-1][-400:]
    n = min(map(len, close.values()))
    close = {a: x[-n:] for a, x in close.items()}
    ret = {a: np.diff(close[a]) / np.maximum(close[a][:-1], 1e-12) for a in ASSETS}
    v20 = {a: max(float(np.std(ret[a][-20:], ddof=1)), .004) for a in ASSETS}
    v60 = {a: max(float(np.std(ret[a][-60:], ddof=1)), .004) for a in ASSETS}
    medv = max(float(np.median(list(v20.values()))), .004)
    raw = {a: {} for a in ASSETS}
    for a in ASSETS:
        p, r = close[a], ret[a]
