        raw[a]["miner_2_20301212_efficiency_reversal_60d"] = -r60 / v60[a] * (1 + abs(loc - .5))
        raw[a]["miner_3_20300822_volatility_dispersion_60d"] = -(v20[a] / medv - 1)
    score = {a: 0. for a in ASSETS}
