ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
_calls = 0

def get_factors():
    try:
        fs = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
        return fs if fs and abs(sum(float(f["weight"]) for f in fs) - 1.0) < 1e-6 else []
    except Exception:
        return []

def ranks(values):
    good = [a for a in ASSETS if np.isfinite(values.get(a, np.nan))]
    out = {a: .5 for a in ASSETS}
    for i, a in enumerate(sorted(good, key=lambda a: values[a])):
        out[a] = (i + 1.) / len(good)
    return out

@register_hook
def strategy():
    global _calls
    if _calls % 10:
        _calls += 1
        return
    _calls += 1
    factors = get_factors()
    if not factors:
        return
    closes = {}
    for a in ASSETS:
        d = get_stock_daily_data(symbol=a, days=450)
        if d is None or len(d) < 180:
            return
        x = np.asarray(d.sort_values("date")["close"], dtype=float)
        closes[a] = x[:-1][-400:]  # only completed bars
    n = min(len(x) for x in closes.values())
    closes = {a: x[-n:] for a, x in closes.items()}
    rets = {a: np.diff(closes[a]) / np.maximum(closes[a][:-1], 1e-12) for a in ASSETS}
    v20 = {a: max(float(np.std(rets[a][-20:], ddof=1)), .004) for a in ASSETS}
    v60 = {a: max(float(np.std(rets[a][-60:], ddof=1)), .004) for a in ASSETS}
    medv = max(float(np.median(list(v20.values()))), .004)
    market = np.mean([closes[a][-1] / closes[a][-61] - 1 for a in ASSETS])
    raw = {a: {} for a in ASSETS}
    for a in ASSETS:
        p, r = closes[a], rets[a]
        r20, r60, r120 = p[-1]/p[-21]-1, p[-1]/p[-61]-1, p[-1]/p[-121]-1
        hi, lo = max(p[-61:]), min(p[-61:])
        recovery = (p[-1] - lo) / max(hi - lo, 1e-12)
        # Deterministic price-only implementations of the persisted factor IDs.
        raw[a]["miner_1_20301031_riskadjusted_momentum_60d"] = r120 / v60[a]
        raw[a]["miner_2_20321028_long_trend_quality_60d"] = r60 / v60[a]
        raw[a]["miner_2_20301212_efficiency_reversal_60d"] = -r60 / v60[a] * (1 + abs(recovery - .5))
        raw[a]["miner_1_20320624_peak_drawdown_recovery_60d"] = recovery / v60[a]
        raw[a]["miner_1_20320401_dispersion_recovery_reversal_60d"] = -r60 / v60[a] * (1 + abs(v20[a]/medv - 1))
