        raw[a]["miner_3_20300822_volatility_dispersion_60d"] = -(v60[a]/max(float(np.median(list(v60.values()))), .004)-1)
    score = {a: 0.0 for a in ASSETS}
    for f in factors:
        fid, direction = str(f["factor_id"]), int(f.get("direction", 1))
        if fid not in raw[ASSETS[0]]:
            return
        rr = ranks({a: raw[a][fid] for a in ASSETS})
        for a in ASSETS:
            score[a] += float(f["weight"]) * direction * rr[a]
