        for a in ("BTC", "ETH", "WTI"):
            score[a] -= .06
    z = (np.array([score[a] for a in ASSETS]) - np.mean(list(score.values()))) / max(np.std(list(score.values())), 1e-9)
    w = np.maximum(np.exp(.08 * np.clip(z, -1.5, 1.5)), .025)
    w /= w.sum()
    target = {a: float(w[i]) for i, a in enumerate(ASSETS)}
    forecast = {a: float(.005 * z[i]) for i, a in enumerate(ASSETS)}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=[str(f["factor_id"]) for f in factors], horizon_days=10)

