def load_factors():
    try:
        fs = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
        if fs and abs(sum(float(x["weight"]) for x in fs) - 1.0) < 1e-6:
            return fs
    except Exception:
        pass
    return []


def cross_rank(values):
    valid = sorted([a for a in ASSETS if np.isfinite(values.get(a, np.nan))], key=lambda a: values[a])
    out = {a: 0.5 for a in ASSETS}
    for i, a in enumerate(valid):
        out[a] = (i + 1.0) / len(valid)
    return out


@register_hook
def strategy():
    global _calls
    if _calls % 10:
        _calls += 1
        return
    _calls += 1
    fs = load_factors()
    if not fs:
        return

    close = {}
    for a in ASSETS:
        d = get_stock_daily_data(symbol=a, days=450)
        if d is None or len(d) < 180:
            return
        # Last row can be an incomplete current session; decisions use prior bars only.
        x = np.asarray(d.sort_values("date")["close"], dtype=float)[:-1]
        close[a] = x[-400:]
