    v60 = {a: max(float(np.std(ret[a][-60:], ddof=1)), .004) for a in ASSETS}
    med20 = max(float(np.median(list(v20.values()))), .004)
    med60 = max(float(np.median(list(v60.values()))), .004)
    market = float(np.mean([close[a][-1] / close[a][-61] - 1 for a in ASSETS]))
