        raw[a]["miner_2_20321028_long_trend_quality_60d"] = r60 / v60[a]
        raw[a]["miner_2_20301212_efficiency_reversal_60d"] = -r60 / v60[a] * (1 + abs(recovery - .5))
        raw[a]["miner_1_20330203_macro_residual_reversal_vixdxy_60d"] = -r20 / v60[a] - .25 * market / dispersion
        raw[a]["miner_3_20300822_volatility_dispersion_60d"] = -(v60[a] / med60 - 1.0)
        raw[a]["miner_3_20330623_residual_reversal_60d"] = -r60 / v60[a]
        raw[a]["miner_1_20320624_peak_drawdown_recovery_60d"] = recovery / v60[a]
        raw[a]["miner_1_20320401_dispersion_recovery_reversal_60d"] = -r60 / v60[a] * (1 + abs(v20[a] / med20 - 1))
        raw[a]["miner_1_20330623_downside_asymmetry_40d"] = -r20 / max(downside, .004)

