    # High-risk rebound: retain full investment while favoring defensive tradables.
    breadth = float(np.mean([np.mean(ret[a][-20:] > 0) for a in ASSETS]))
    if market < 0 or breadth < .50:
        for a in ("XAU", "US10Y", "CN10Y"):
            score[a] += .10
        for a in ("BTC", "ETH", "WTI"):
            score[a] -= .05

    s = np.array([score[a] for a in ASSETS], dtype=float)
    z = (s - s.mean()) / max(float(s.std()), 1e-9)
    w = np.maximum(np.exp(.08 * np.clip(z, -1.5, 1.5)), .025)
    w /= w.sum()
    target = {a: float(w[i]) for i, a in enumerate(ASSETS)}
    forecast = {a: float(.005 * np.clip(z[i], -1.5, 1.5)) for i, a in enumerate(ASSETS)}
