def load_factors():
    try:
        fs = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
        if fs and abs(sum(float(x["weight"]) for x in fs) - 1.0) < 1e-6:
            return fs
    except Exception:
        pass
    return []


def rank(values):
    good = [a for a in ASSETS if np.isfinite(values.get(a, np.nan))]
    good.sort(key=lambda a: values[a])
    out = {a: 0.5 for a in ASSETS}
    for i, a in enumerate(good):
        out[a] = (i + 1.0) / len(good)
    return out


