    w = np.maximum(np.exp(0.08 * z), 0.025)
    w /= w.sum()
    target = {a: float(w[i]) for i, a in enumerate(ASSETS)}
    forecast = {a: float(0.005 * z[i]) for i, a in enumerate(ASSETS)}
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=[str(f["factor_id"]) for f in factors], horizon_days=10)

