ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
_calls = 0

def load_factors():
    try:
        fs = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
        if not fs or abs(sum(float(f["weight"]) for f in fs) - 1.0) > 1e-6:
            return []
        return fs
    except Exception:
        return []

def rank(values):
    good = sorted((a for a in ASSETS if np.isfinite(values.get(a, np.nan))),
                  key=lambda a: values[a])
    out = {a: 0.5 for a in ASSETS}
    for i, a in enumerate(good):
        out[a] = (i + 1) / len(good)
    return out

@register_hook
def strategy():
    global _calls
    if _calls % 10:
        _calls += 1
        return
    _calls += 1
    factors = load_factors()
    if not factors:
        return

    prices = {}
    for a in ASSETS:
        df = get_stock_daily_data(symbol=a, days=450)
        if df is None or len(df) < 180:
            return
        close = np.asarray(df.sort_values("date")["close"], dtype=float)
        # Exclude the possibly incomplete current observation.
        prices[a] = close[:-1]
    n = min(map(len, prices.values()))
    prices = {a: x[-n:] for a, x in prices.items()}
    returns = {a: np.diff(prices[a]) / np.maximum(prices[a][:-1], 1e-12) for a in ASSETS}
    v20 = {a: max(float(np.std(returns[a][-20:], ddof=1)), .004) for a in ASSETS}
    v60 = {a: max(float(np.std(returns[a][-60:], ddof=1)), .004) for a in ASSETS}
    med20 = max(float(np.median(list(v20.values()))), .004)
    r10 = {a: prices[a][-1] / prices[a][-11] - 1 for a in ASSETS}
    r20 = {a: prices[a][-1] / prices[a][-21] - 1 for a in ASSETS}
    r60 = {a: prices[a][-1] / prices[a][-61] - 1 for a in ASSETS}
    r120 = {a: prices[a][-1] / prices[a][-121] - 1 for a in ASSETS}
    breadth = {a: float(np.mean(returns[a][-20:] > 0)) for a in ASSETS}
    cross60 = float(np.mean(list(r60.values())))
    raw = {a: {} for a in ASSETS}
    for a in ASSETS:
        path = float(np.sum(np.abs(returns[a][-60:]))) + 1e-12
        raw[a]["miner_1_20301031_riskadjusted_momentum_60d"] = -r120[a] / v60[a]
        raw[a]["miner_2_20301212_efficiency_reversal_60d"] = -(r60[a] / path) / v20[a]
        raw[a]["miner_2_20301114_compressed_trend_reversal_60d"] = (-r60[a] / v60[a]) * np.clip(v60[a] / v20[a], .5, 2.)
        raw[a]["miner_1_20331124_breadth_confirmed_momentum_60d"] = (r60[a] / v60[a]) * 2 * (breadth[a] - .5)
        raw[a]["miner_1_20320624_peak_drawdown_recovery_60d"] = ((1 - prices[a][-1] / max(prices[a][-121:])) / v60[a]) * (.5 + max(float(np.sum(returns[a][-10:])), 0))
        raw[a]["miner_1_20320401_dispersion_recovery_reversal_60d"] = (cross60 - r60[a]) / v60[a] * (1 + .25 * np.clip(r10[a] / (v20[a] * np.sqrt(10)), -1, 1))
        raw[a]["miner_3_20300822_volatility_dispersion_60d"] = -(v20[a] / med20 - 1)

    score = {a: 0.0 for a in ASSETS}
    for f in factors:
        ranks = rank({a: raw[a].get(f["factor_id"], np.nan) for a in ASSETS})
        for a in ASSETS:
            score[a] += float(f["weight"]) * int(f.get("direction", 1)) * ranks[a]

    mean20 = float(np.mean(list(r20.values())))
    mean60 = float(np.mean(list(r60.values())))
    if mean60 < 0 or mean20 < 0 or float(np.mean(list(breadth.values()))) < .5:
