            score[a] -= .05

    s = np.array([score[a] for a in ASSETS])
    z = np.clip((s - s.mean()) / max(float(s.std()), 1e-9), -1.5, 1.5)
    weights = np.maximum(np.exp(.08 * z), .025)
    weights /= weights.sum()
    target = {a: float(weights[i]) for i, a in enumerate(ASSETS)}
    forecast = {a: float(.005 * z[i]) for i, a in enumerate(ASSETS)}
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=[str(f["factor_id"]) for f in factors],
                         horizon_days=10)

