ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
_calls = 0

def load_factors():
    try:
        fs = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
        return fs if fs and abs(sum(float(f["weight"]) for f in fs)-1) < 1e-6 else []
    except Exception:
        return []

def cs_rank(d):
    vals = {a: d.get(a, np.nan) for a in ASSETS}
    good = sorted([a for a in ASSETS if np.isfinite(vals[a])], key=lambda a: vals[a])
    out = {a: .5 for a in ASSETS}
    for i, a in enumerate(good): out[a] = (i + 1) / len(good)
    return out

@register_hook
def strategy():
    global _calls
    if _calls % 10: _calls += 1; return
    _calls += 1
    factors = load_factors()
    if not factors: return
    px = {}
    for a in ASSETS:
        df = get_stock_daily_data(symbol=a, days=450)
        if df is None or len(df) < 180: return
        # Last row can be an in-progress observation; use completed history only.
        x = np.asarray(df.sort_values("date")["close"], dtype=float)
        px[a] = x[:-1]
    n = min(len(x) for x in px.values()); px = {a:x[-n:] for a,x in px.items()}
    ret = {a: np.diff(px[a]) / np.maximum(px[a][:-1], 1e-12) for a in ASSETS}
    v20 = {a:max(np.std(ret[a][-20:], ddof=1), .004) for a in ASSETS}
    v60 = {a:max(np.std(ret[a][-60:], ddof=1), .004) for a in ASSETS}
    med20 = max(np.median(list(v20.values())), .004)
    r10 = {a:px[a][-1]/px[a][-11]-1 for a in ASSETS}
    r20 = {a:px[a][-1]/px[a][-21]-1 for a in ASSETS}
    r60 = {a:px[a][-1]/px[a][-61]-1 for a in ASSETS}
    r120 = {a:px[a][-1]/px[a][-121]-1 for a in ASSETS}
    breadth = {a:np.mean(ret[a][-20:] > 0) for a in ASSETS}
    cross60 = np.mean(list(r60.values()))
    raw = {a:{} for a in ASSETS}
    for a in ASSETS:
        # Each expression is lagged implicitly by using only completed rows.
        raw[a]["miner_1_20301031_riskadjusted_momentum_60d"] = -r120[a] / v60[a]
        path = np.sum(np.abs(ret[a][-60:])) + 1e-12
        raw[a]["miner_2_20301212_efficiency_reversal_60d"] = -(r60[a]/path) / v20[a]
        raw[a]["miner_2_20301114_compressed_trend_reversal_60d"] = (-r60[a]/v60[a]) * np.clip(v60[a]/v20[a], .5, 2.)
        raw[a]["miner_1_20331124_breadth_confirmed_momentum_60d"] = (r60[a]/v60[a]) * 2*(breadth[a]-.5)
        raw[a]["miner_1_20320624_peak_drawdown_recovery_60d"] = ((1-px[a][-1]/max(px[a][-121:]))/v60[a]) * (.5+max(np.sum(ret[a][-10:]),0))
        raw[a]["miner_1_20320401_dispersion_recovery_reversal_60d"] = (cross60-r60[a]) / v60[a] * (1+.25*np.clip(r10[a]/(v20[a]*np.sqrt(10)), -1, 1))
        raw[a]["miner_3_20300822_volatility_dispersion_60d"] = -(v20[a]/med20-1)
        # Observation-only macro series are deliberately not traded; use cross-section residual proxy.
        raw[a]["miner_1_20330203_macro_residual_reversal_vixdxy_60d"] = -(r60[a]-cross60)/v60[a]
    score = {a:0. for a in ASSETS}
    for f in factors:
        rr = cs_rank({a:raw[a].get(f["factor_id"], np.nan) for a in ASSETS})
        for a in ASSETS: score[a] += float(f["weight"])*int(f.get("direction",1))*rr[a]
    m20, m60 = np.mean(list(r20.values())), np.mean(list(r60.values()))
    # High-risk bearish regime: full investment is retained in defensive tradable assets.
    if m60 < 0 or m20 < 0 or np.mean(list(breadth.values())) < .5:
        for a in ("XAU","US10Y","CN10Y"): score[a] += .10
        for a in ("BTC","ETH","WTI"): score[a] -= .05
    z = np.clip((np.array([score[a] for a in ASSETS])-np.mean(list(score.values()))) / max(np.std(list(score.values())),1e-9), -1.5, 1.5)
    w = np.maximum(np.exp(.08*z), .025); w /= w.sum()
    target = {a:float(w[i]) for i,a in enumerate(ASSETS)}
    forecast = {a:float(.005*z[i]) for i,a in enumerate(ASSETS)}
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=[str(f["factor_id"]) for f in factors], horizon_days=10)
"}

