import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
_calls = 0

def factors():
    try:
        x = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
        return x if x and abs(sum(float(f["weight"]) for f in x) - 1.0) < 1e-5 else []
    except Exception:
        return []

def rank(v):
    good = sorted([a for a in ASSETS if np.isfinite(v.get(a, np.nan))], key=lambda a: v[a])
    out = {a: 0.5 for a in ASSETS}
    for i, a in enumerate(good): out[a] = (i + 1) / len(good)
    return out

@register_hook
def strategy():
    global _calls
    if _calls % 10:
        _calls += 1
        return
    _calls += 1
    fs = factors()
    if not fs: return
    close, high, low = {}, {}, {}
    for a in ASSETS:
        d = get_stock_daily_data(symbol=a, days=450)
        if d is None or len(d) < 180: return
        d = d.sort_values("date").iloc[:-1]
        close[a] = np.asarray(d.close, dtype=float)
        high[a] = np.asarray(d.high, dtype=float)
        low[a] = np.asarray(d.low, dtype=float)
    n = min(map(len, close.values()))
    close = {a: x[-n:] for a, x in close.items()}
    high = {a: x[-n:] for a, x in high.items()}
    low = {a: x[-n:] for a, x in low.items()}
    ret = {a: np.diff(close[a]) / np.maximum(close[a][:-1], 1e-12) for a in ASSETS}
    r20 = {a: close[a][-1] / close[a][-21] - 1 for a in ASSETS}
    r60 = {a: close[a][-1] / close[a][-61] - 1 for a in ASSETS}
    v20 = {a: max(float(np.std(ret[a][-20:], ddof=1)), .004) for a in ASSETS}
    v30 = {a: max(float(np.std(ret[a][-30:], ddof=1)), .004) for a in ASSETS}
    v60 = {a: max(float(np.std(ret[a][-60:], ddof=1)), .004) for a in ASSETS}
    median_v = max(float(np.median(list(v20.values()))), .004)
    breadth = float(np.mean([r20[a] > 0 for a in ASSETS]))
    market60 = float(np.mean(list(r60.values())))
    raw = {a: {} for a in ASSETS}
    for a in ASSETS:
        path = float(np.sum(np.abs(ret[a][-60:]))) + 1e-12
        raw[a]["miner_1_20301031_riskadjusted_momentum_60d"] = r60[a] / v60[a]
        raw[a]["miner_2_20301114_compressed_trend_reversal_60d"] = (-r60[a] / v60[a]) * np.clip(v60[a] / v20[a], .5, 2.)
        raw[a]["miner_2_20301212_efficiency_reversal_60d"] = (-r60[a] / path) / (v20[a] * np.sqrt(252) + 1e-8)
        peak = max(close[a][-120:])
        raw[a]["miner_1_20320624_peak_drawdown_recovery_60d"] = max(0., 1 - close[a][-1] / peak) / v60[a]
        rng = float(np.mean((high[a][-20:] - low[a][-20:]) / np.maximum(close[a][-20:], 1e-12)))
        base = float(np.median([np.mean((high[b][-20:] - low[b][-20:]) / np.maximum(close[b][-20:], 1e-12)) for b in ASSETS]))
        raw[a]["miner_3_20301128_range_stressed_reversal_60d"] = (-r20[a] / v30[a]) * np.clip(rng / max(base, 1e-6), .5, 2.)
        raw[a]["miner_1_20331124_breadth_confirmed_momentum_60d"] = (r60[a] / v60[a]) * (.5 + breadth)
        raw[a]["miner_3_20300822_volatility_dispersion_60d"] = -(v20[a] / median_v - 1.)
        raw[a]["miner_1_20330203_macro_residual_reversal_vixdxy_60d"] = -(r60[a] - market60) / v60[a]
    score = {a: 0.0 for a in ASSETS}
    for f in fs:
        rr = rank({a: raw[a].get(f["factor_id"], np.nan) for a in ASSETS})
        for a in ASSETS: score[a] += float(f["weight"]) * int(f.get("direction", 1)) * rr[a]
    if market60 < 0 or breadth < .5:
        for a in ("XAU", "US10Y", "CN10Y"): score[a] += .10
        for a in ("BTC", "ETH", "WTI"): score[a] -= .05
    mean, sd = np.mean(list(score.values())), max(float(np.std(list(score.values()))), 1e-9)
    z = np.clip([(score[a] - mean) / sd for a in ASSETS], -1.5, 1.5)
    w = np.maximum(np.exp(.08 * np.asarray(z)), .025); w /= w.sum()
    target = {a: float(w[i]) for i, a in enumerate(ASSETS)}
    forecast = {a: float(.005 * z[i]) for i, a in enumerate(ASSETS)}
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=[str(f["factor_id"]) for f in fs], horizon_days=10)

