from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
_calls = 0

def load_ensemble():
    try:
        fs = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
        return fs if fs and abs(sum(float(x["weight"]) for x in fs) - 1.0) < 1e-5 else []
    except Exception:
        return []

def rank(v):
    good = sorted([a for a in ASSETS if np.isfinite(v.get(a, np.nan))], key=lambda a: v[a])
    out = {a: .5 for a in ASSETS}
    for i, a in enumerate(good): out[a] = (i + 1.) / len(good)
    return out

def macro_return(symbol):
    try:
        d = get_index_daily_data(symbol=symbol, days=100)
        if d is not None and len(d) > 61:
            x = np.asarray(d.sort_values("date")["close"], dtype=float)[:-1]
            return float(x[-1] / x[-61] - 1.)
    except Exception:
        pass
    return 0.

@register_hook
def strategy():
    global _calls
    if _calls % 10:
        _calls += 1
        return
    _calls += 1
    fs = load_ensemble()
    if not fs: return
    close, volume = {}, {}
    for a in ASSETS:
        d = get_stock_daily_data(symbol=a, days=450)
        if d is None or len(d) < 180: return
        d = d.sort_values("date").iloc[:-1]
        close[a] = np.asarray(d["close"], dtype=float)
        volume[a] = np.asarray(d["volume"], dtype=float)
    n = min(len(x) for x in close.values())
    close = {a: x[-n:] for a, x in close.items()}
    volume = {a: x[-n:] for a, x in volume.items()}
    ret = {a: np.diff(close[a]) / np.maximum(close[a][:-1], 1e-12) for a in ASSETS}
    r60 = {a: close[a][-1] / close[a][-61] - 1. for a in ASSETS}
    r20 = {a: close[a][-1] / close[a][-21] - 1. for a in ASSETS}
    v20 = {a: max(float(np.std(ret[a][-20:], ddof=1)), .004) for a in ASSETS}
    v60 = {a: max(float(np.std(ret[a][-60:], ddof=1)), .004) for a in ASSETS}
    medv = max(float(np.median(list(v20.values()))), .004)
    market60 = float(np.mean(list(r60.values())))
    breadth = float(np.mean([r20[a] > 0 for a in ASSETS]))
    vr = {a: float(np.mean(volume[a][-20:]) / max(np.mean(volume[a][-60:]), 1e-12)) for a in ASSETS}
    macro = macro_return("VIX") - macro_return("DXY")
    raw = {a: {} for a in ASSETS}
    for a in ASSETS:
        # All inputs are lagged through the last completed session.
        raw[a]["miner_1_20301031_riskadjusted_momentum_60d"] = r60[a] / v60[a]
        raw[a]["miner_2_20301212_efficiency_reversal_60d"] = (-r60[a] / (np.sum(np.abs(ret[a][-60:])) + 1e-12)) / v20[a]
        raw[a]["miner_1_20330203_macro_residual_reversal_vixdxy_60d"] = -(r60[a] - market60) / v60[a] * (1. + np.tanh(abs(macro)))
        raw[a]["miner_2_20301114_compressed_trend_reversal_60d"] = -r60[a] / v60[a] * np.clip(v60[a] / v20[a], .5, 2.)
        raw[a]["miner_3_20300822_volatility_dispersion_60d"] = -(v20[a] / medv - 1.)
        raw[a]["miner_2_20301128_volume_shock_reversal_60d"] = -r20[a] * (vr[a] - 1.) / v20[a]
    score = {a: 0. for a in ASSETS}
    for f in fs:
        rr = rank({a: raw[a].get(f["factor_id"], np.nan) for a in ASSETS})
        for a in ASSETS: score[a] += float(f["weight"]) * int(f.get("direction", 1)) * rr[a]
    stressed = market60 < 0 or breadth < .5
    if stressed:
        for a in ("XAU", "US10Y", "CN10Y"): score[a] += .15
        for a in ("BTC", "ETH", "WTI"): score[a] -= .08
    mean, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-9)
    z = np.clip(np.array([(score[a] - mean) / sd for a in ASSETS]), -1.25, 1.25)
    w = np.maximum(np.exp(.05 * z), .04); w /= w.sum()
    target = {a: float(w[i]) for i, a in enumerate(ASSETS)}
    forecast = {a: float(.008 * z[i]) for i, a in enumerate(ASSETS)}
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=[str(f["factor_id"]) for f in fs], horizon_days=10)

