import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX",
          "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
_calls = 0


def load_ensemble():
    try:
        fs = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])[:10]
        if fs and abs(sum(float(x["weight"]) for x in fs) - 1.0) < 1e-5:
            return fs
    except Exception:
        pass
    return []


def cross_rank(values):
    valid = sorted((a for a in ASSETS if np.isfinite(values.get(a, np.nan))),
                   key=lambda a: values[a])
    out = {a: 0.5 for a in ASSETS}
    for i, a in enumerate(valid):
        out[a] = (i + 1.0) / len(valid)
    return out


def macro_return(symbol):
    try:
        d = get_index_daily_data(symbol=symbol, days=100)
        if d is not None and len(d) > 61:
            x = np.asarray(d.sort_values("date")["close"], float)[:-1]
            return float(x[-1] / max(x[-61], 1e-12) - 1.0)
    except Exception:
        pass
    return 0.0


@register_hook
def strategy():
    global _calls
    if _calls % 10:
        _calls += 1
        return
    _calls += 1
    factors = load_ensemble()
    if not factors:
        return

    closes = {}
    for asset in ASSETS:
        d = get_stock_daily_data(symbol=asset, days=450)
        if d is None or len(d) < 180:
            return
        # The last completed bar is the latest information permitted at a decision.
        closes[asset] = np.asarray(d.sort_values("date")["close"], float)[:-1]
    n = min(map(len, closes.values()))
    closes = {a: x[-n:] for a, x in closes.items()}
    returns = {a: np.diff(closes[a]) / np.maximum(closes[a][:-1], 1e-12) for a in ASSETS}

    r10 = {a: closes[a][-1] / max(closes[a][-11], 1e-12) - 1 for a in ASSETS}
    r60 = {a: closes[a][-1] / max(closes[a][-61], 1e-12) - 1 for a in ASSETS}
    r120 = {a: closes[a][-1] / max(closes[a][-121], 1e-12) - 1 for a in ASSETS}
    v20 = {a: max(float(np.std(returns[a][-20:], ddof=1)), .004) for a in ASSETS}
    v60 = {a: max(float(np.std(returns[a][-60:], ddof=1)), .004) for a in ASSETS}
    median_v = max(float(np.median(list(v20.values()))), .004)
    market60 = float(np.mean(list(r60.values())))
    breadth = float(np.mean([r10[a] > 0 for a in ASSETS]))
    macro = macro_return("VIX") - macro_return("DXY")

    raw = {a: {} for a in ASSETS}
    for a in ASSETS:
        path = np.sum(np.abs(returns[a][-60:])) + 1e-12
        drawdown = closes[a][-1] / max(np.max(closes[a][-121:]), 1e-12) - 1
        raw[a]["miner_1_20301031_riskadjusted_momentum_60d"] = -r120[a] / v60[a]
        raw[a]["miner_2_20301114_compressed_trend_reversal_60d"] = (
            -r60[a] / v60[a] * np.clip(v60[a] / v20[a], .5, 2.))
        raw[a]["miner_2_20301212_efficiency_reversal_60d"] = -(r60[a] / path) / v60[a]
        raw[a]["miner_1_20330203_macro_residual_reversal_vixdxy_60d"] = (
            -(r60[a] - market60) / v60[a] * (1 + np.tanh(abs(macro))))
        raw[a]["miner_1_20320624_peak_drawdown_recovery_60d"] = (
            -drawdown / (v60[a] * np.sqrt(60)) *
            (.5 + max(float(np.sum(returns[a][-10:])), 0)))
        raw[a]["miner_3_20301114_breadth_gated_contrarian_60d"] = (
            -r10[a] * (1 + .5 * (1 - breadth)))
        raw[a]["miner_3_20300822_volatility_dispersion_60d"] = -(v20[a] / median_v - 1)

    score = {a: 0.0 for a in ASSETS}
    for factor in factors:
        ranks = cross_rank({a: raw[a].get(factor["factor_id"], np.nan) for a in ASSETS})
        for a in ASSETS:
            score[a] += float(factor["weight"]) * int(factor.get("direction", 1)) * ranks[a]
    if market60 < 0 or breadth < .5:
        for a in ("XAU", "US10Y", "CN10Y"):
            score[a] += .15
        for a in ("BTC", "ETH", "WTI"):
            score[a] -= .08

    values = np.array([score[a] for a in ASSETS])
    z = np.clip((values - values.mean()) / max(values.std(), 1e-9), -1.25, 1.25)
    weights = np.maximum(np.exp(.035 * z), .045)
    weights /= weights.sum()
    target = {a: float(weights[i]) for i, a in enumerate(ASSETS)}
    forecast = {a: float(.006 * z[i]) for i, a in enumerate(ASSETS)}
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=[str(f["factor_id"]) for f in factors],
                         horizon_days=10)

